public class AirTrapDash : BaseDashState
{
	public new static string staticID = "AirTrapDash";

	public AirTrapDash(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		isProjectileSkill = true;
		InitChargeSkillSettings(2, 0f, skillData, this);
	}

	public override void OnExit()
	{
		base.OnExit();
		if (cooldownReady)
		{
			ChaosInst<AirSlideTrap>(AirSlideTrap.Prefab, parent.transform.position).Initialize(parent.skillCategory, skillID, -inputVector, IsEmpowered, parent);
		}
	}
}

public class AquaCrestBasic : MeleeAttackState
{
	public new static string staticID = "AquaCrestBasic";

	private static float baseExecTime = 0.2f;

	private static int maxCrestCount = 3;

	private int crestCounter = 1;

	private Vector2 currentPosition;

	private Vector2 perpendVec;

	private AquaCrest currentAC;

	public AquaCrestBasic(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isBasic = true;
		isProjectileSkill = true;
		destroyAttackObjectOnExit = false;
		maxComboCount = 1;
		alwaysStartForehand = true;
		animStartTime = 0.1f;
		animExecTime = baseExecTime;
		baseCancelThreshold = 0.6f;
		finalCancelThreshold = 0.7f;
		baseRunThreshold = 0.75f;
		finalRunThreshold = 0.85f;
		baseExitThreshold = 1f;
		finalExitThreshold = 1f;
		flipObjectForBackhand = false;
		attackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 0.125f, 10, VarStatModType.OverrideWithMods);
		finalAttackMoveSpeedMod = attackMoveSpeedMod;
		sfxNames = new string[maxComboCount];
		for (int i = 0; i < maxComboCount; i++)
		{
			sfxNames[i] = "WaterArcBasic";
		}
	}

	public override void PlayAnimation(int attackCount)
	{
		parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, animStartTime);
	}

	public override void OnEnter()
	{
		skipAttackEvent = false;
		animExecTime = baseExecTime;
		crestCounter = 1;
		base.OnEnter();
	}

	public override void ExecuteAttack()
	{
		HandleComboCount(comboCounter);
		HandleSelfTransition(comboCounter);
		AnnounceSkillExecuteEvent();
		skipAttackEvent = true;
		currentPosition = parent.attackOriginTrans.position;
		CreateAquaCrest(currentPosition, inputVector);
		if (crestCounter < maxCrestCount)
		{
			attackExecuted = false;
			animExecTime = baseExecTime + (float)crestCounter * 0.15f;
			crestCounter++;
		}
		else if (IsEmpowered)
		{
			perpendVec = Globals.GetPerpendicular(inputVector) * 0.45f;
			CreateAquaCrest(currentPosition, (inputVector + perpendVec).normalized);
			CreateAquaCrest(currentPosition, (inputVector - perpendVec).normalized);
		}
	}

	private void CreateAquaCrest(Vector2 givenPosition, Vector2 givenVector)
	{
		currentAC = (AquaCrest)Projectile.CreateProjectile(parent, AquaCrest.Prefab, givenPosition + givenVector * 0.75f, Globals.GetRotationQuaternion(givenVector));
		currentAC.attackBox.SetAttackInfo(parent.skillCategory, skillID, crestCounter);
		currentAC.attackBox.knockbackOverwriteVector = givenVector;
		currentAC.moveVector = givenVector;
		currentAC.UpdateCalculatedDamage(initDamageOverride: true);
	}
}

public class BaseDashState : SkillState
{
	public bool showEffects = true;

	public bool playSFX = true;

	public bool cooldownReady;

	public bool prevCDWasReady;

	public bool finishedDashing;

	public float dashDuration = 0.125f;

	public NumVarStatMod dashDurationMod;

	public BoolVarStat forceEvadeStat;

	public NumVarStatMod evadeMod;

	public BoolVarStatMod airborneMod;

	public BaseDashState(string skillID, FSM fsm, Player player)
		: base(skillID, fsm, player)
	{
		isDash = true;
		isMovementSkill = true;
		forceEvadeStat = new BoolVarStat(newBaseVal: false);
		evadeMod = new NumVarStatMod("DashEvade", 1f, 10, VarStatModType.Override);
		airborneMod = new BoolVarStatMod(SkillState.staticID, newModValue: true);
		dashDurationMod = new NumVarStatMod("dashOverride", dashDuration, 10, VarStatModType.OverrideWithMods);
	}

	public override bool IsReady()
	{
		return parent.MovementEnabled && (!allowSelfTransition || allowRepeating || !repeatLock) && (!isUltimate || IsOverdriveReady());
	}

	public override void OnEnter()
	{
		if (parent.dashSlideIgnored)
		{
			cooldownReady = prevCDWasReady;
			disableStartCooldown = true;
		}
		else
		{
			cooldownReady = cooldownRef.Ready;
			prevCDWasReady = cooldownReady;
			disableStartCooldown = !cooldownReady;
		}
		parent.dashSlideIgnored = false;
		BaseOnEnter();
		if (forceEvadeStat.CurrentValue)
		{
			parent.health.evadeStat.AddMod(evadeMod);
		}
		finishedDashing = false;
		dashDurationMod.modValue = dashDuration;
		parent.movement.dashDurationStat.AddMod(dashDurationMod);
		parent.movement.dashTimer = dashDuration;
		if (parent.inputDevice == null)
		{
			inputVector = Vector2.zero;
		}
		else if (parent.inputDevice.IsMouseDash)
		{
			inputVector = GetInputVector();
		}
		else
		{
			inputVector = GetInputVector(faceInputVector: true, (parent.inputDevice.inputScheme == ChaosInputDevice.InputScheme.Gamepad && ChaosInputDevice.lockControllerAim) ? true : false);
		}
		parent.movement.dashVector = inputVector;
		parent.anim.PlayDirectional(parent.DashAnimStr);
		if (showEffects && !cooldownReady)
		{

		{
			PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.attackOriginTrans.position, inputVector);
			parent.dustEmitter.EmitDirBurst(15, Globals.GetRotationVector(-inputVector).z);
			parent.dashTrails.SetActive(value: true);
		}
		if (playSFX)
		{
			SoundManager.PlayWithDistAndSPR("StandardDash", parent.transform.position);
		}
		parent.TogglePreventFallCollider(status: false);
		parent.ToggleEnemyFloorCollisions(status: false);
		parent.airborneStat.AddMod(airborneMod);
		AnnounceSkillExecuteEvent();
	}
	public override void Update()
	{
		if (finishedDashing)
		{
			ExitTransition();
		}
	}
	public override void FixedUpdate()
	{
		if (!finishedDashing)
		{
			finishedDashing = parent.movement.DashToTarget();
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		parent.movement.dashDurationStat.RemoveMod(dashDurationMod.ID);
		DashFinished();
		if (forceEvadeStat.CurrentValue)
		{
			parent.health.evadeStat.RemoveMod(evadeMod);
		}
	}
	public virtual void DashFinished()
	{
		parent.dashTrails.SetActive(value: false);
		parent.TogglePreventFallCollider(status: true);
		parent.airborneStat.RemoveMod(airborneMod);
		parent.ToggleEnemyFloorCollisions();
		parent.movement.EndMovement();
	}
	public virtual void ExitTransition()
	{
		fsm.ChangeState(SlideState.staticID);
	}
}
public class BaseJumpState : SkillState
{
	protected ThrownItem parentThrow;
	protected Vector2 startPosition;
	protected bool useCalcValues;
	protected float jumpRange = 5.5f;
	protected float jumpSpeed = 32f;
	protected float jumpTime = 0.5f;
	protected float jumpHeight = 1f;
	protected float jumpBalance = 0.5f;
	protected bool hasLanded;
	protected bool collidersEnabled;
	protected float landingDelay;
	protected ChaosQuickStopwatch landingStopwatch = new ChaosQuickStopwatch();
	public bool setInputVectorOnEnter = true;
	protected BoolVarStatMod airborneStatMod;
	public BaseJumpState(string skillID, FSM fsm, Player player)
		: base(skillID, fsm, player)
	{
		isMovementSkill = true;
		isJumpSkill = true;
		parentThrow = parent.throwScript;
		airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 3);
	}
	public override void OnEnter()
	{
		BaseOnEnter();
		base.ExecuteSkill();
		if (setInputVectorOnEnter)
		{
			inputVector = GetInputVector();
		}
		startPosition = parent.transform.position;
		parent.spriteRenderer.sortingLayerName = "UI";
		SetThrowValues();
		parentThrow.ThrowToTargetVector(Globals.GetSafeLinecastVector(startPosition, inputVector, jumpRange, ChaosCollisions.layerAllWallAndObst));
		landingStopwatch.SetDelay(landingDelay);
		SoundManager.PlayAudioWithDistance("StandardJump", startPosition);
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 50;
		float scale = 0.25f;
		Vector3? emitPosition = startPosition;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		hasLanded = false;
		collidersEnabled = false;
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ThrownItem thrownItem2 = parentThrow;
		thrownItem2.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(thrownItem2.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ToggleObjects(status: false);
	}
	public override void Update()
	{
		if (hasLanded)
		{
			if (!collidersEnabled)
			{
				collidersEnabled = true;
				ToggleObjects(status: true);
			}
			if (!landingStopwatch.IsRunning)
			{
				ExitToSkillOrRunOrIdle();
			}
		}
	}
	public override void OnExit()
	{
		if (!hasLanded)
		{
			OnLanding();
		}
		base.OnExit();
		ToggleObjects(status: true);
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
	}
	public virtual void OnLanding()
	{
		hasLanded = true;
		landingStopwatch.IsRunning = true;
		parent.spriteRenderer.sortingLayerName = "Actor";
	}
	public virtual void ToggleObjects(bool status)
	{
		parent.airborneStat.Modify(airborneStatMod, !status);
		if (parent.hurtBoxObj != null && parent.hurtBoxObj.activeSelf != status)
		{
			parent.hurtBoxObj.SetActive(status);
		}
		if (parent.floorContact != null && parent.floorContact.activeSelf != status)
		{
			parent.floorContact.SetActive(status);
		}
		parent.TogglePreventFallCollider(status);
	}
	public virtual void SetThrowValues()
	{
		parentThrow.useCalculatedValues = useCalcValues;
		parentThrow.moveSpeed = jumpSpeed;
		parentThrow.baseFlightTime = jumpTime;
		parentThrow.throwHeight = jumpHeight;
		parentThrow.isFallingThreshold = jumpBalance;
	}
}
public class BaseWardState : SkillState
{
	public GameObject wardPrefab;
	public Ward currentWard;
	private static float spawnRange = 3f;
	private static int maxSpawnCount = 6;
	private float duration = 1f;
	private int spawnCount = 1;
	private int healthValue = 1;
	private Vector2 currentPosition;
	private int maxPosCount;
	private int calcPosCount;
	private int offsetCount;
	private bool skipEvens;
	public override string OnEnterAnimStr => parent.GSlamAnimStr;
	public BaseWardState(string newName, FSM newFSM, Player newPlayer)
		: base(newName, newFSM, newPlayer)
	{
		isBuffSkill = true;
		isSummonSkill = true;
		SetAnimTimes(0.25f, 0.2f, 0.3f, 0.35f, 0.4f);
	}
	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		ApplyStopElement();
		CameraController.ShakeCamera(0.25f);
		duration = skillData.GetValue<float>(StatData.durStr);
		spawnCount = Mathf.Min(maxSpawnCount, skillData.GetValue<int>(StatData.spawnStr));
		healthValue = skillData.GetValue<int>(StatData.healthStr);
		maxPosCount = maxSpawnCount;
		calcPosCount = spawnCount;
		skipEvens = calcPosCount % 2 == 0;
		if (skipEvens)
		{
			calcPosCount *= 2;
			maxPosCount *= 2;
		}
		offsetCount = (int)((float)calcPosCount * 0.5f);
		currentPosition = parent.transform.position;
		for (int i = -offsetCount; i <= offsetCount; i++)
		{
			if (!skipEvens || i % 2 != 0)
			{
				CreateWard(Globals.GetLinecastVector(currentPosition, currentPosition + Globals.GetRotatedCircleVector(maxPosCount, i, inputVector) * spawnRange, ChaosCollisions.layerAllWallAndObst));
			}
		}
	}
	public virtual void CreateWard(Vector2 givenPosition)
	{
		currentWard = ChaosInst<Ward>(wardPrefab, givenPosition);
		currentWard.duration = duration;
		currentWard.startingHealth = healthValue;
		currentWard.attack.SetAttackInfo(parent.skillCategory, skillID);
		currentWard.isEmpowered = IsEmpowered;
		currentWard.gameObject.name = wardPrefab.name + parent.skillCategory;
		parent.playerSummonsList.Add(currentWard.gameObject);
	}
}
