public class BerserkState(FSM parentFSM, Player parentEntity) : UseBuffSkill(staticID, parentFSM, parentEntity)
{
	public new static string staticID = "Berserk";
	private static GameObject effectPrefab;
	private ParticleEffect currentEffect;
	private NumVarStatMod animSpeedMod = new NumVarStatMod(staticID, 0.3f);
	private BoolVarStatMod fullAutoMod = new BoolVarStatMod(staticID, newModValue: true);
	private AudioSource berserkAudio;
	private SkillState basicSkill;
	public static GameObject EffectPrefab
	{
		get
		{
			if (effectPrefab == null)
			{
				effectPrefab = ChaosBundle.Get("Assets/Prefabs/Effects/Fire/BerserkEffect.prefab");
			}
			return effectPrefab;
		}
	}
	public override void SetBuffStatus(bool givenStatus)
	{
		base.SetBuffStatus(givenStatus);
		parent.animSpeedHandler.Modify(animSpeedMod, givenStatus);
		if (IsEmpowered)
		{
			FlameBurst.CreateBurst(attackPosition, parent.skillCategory, skillID, 1, 2.5f).gameObject.AddComponent<NegateProjectiles>().skillCategory = parent.skillCategory;
			SoundManager.PlayAudioWithDistance("ImpactFire", currentPosition);
		}
		if (givenStatus)
		{
			currentEffect = Globals.ChaosInst<ParticleEffect>(EffectPrefab, null, attackPosition);
			currentEffect.Emit(30);
			currentEffect.followTransform = parent.spriteRenderer.transform;
			currentEffect.Play();
			SetFullAutoStatus(basicSkill as MeleeAttackState, givenStatus: false);
			SetNegMeleeStatus(basicSkill as NegMeleeState, givenStatus: true);
			basicSkill = parent.GetBasicSkill();
			if (basicSkill != null)
			{
				parent.overheadPrompt.DisplayPrompt("Slot" + basicSkill.SetSkillSlot(), loop: true);
			}
			SetFullAutoStatus(basicSkill as MeleeAttackState, givenStatus: true);
			SetNegMeleeStatus(basicSkill as NegMeleeState, givenStatus: false);
			SoundManager.PlayAudioWithDistance("FireWallStart", currentPosition);
			berserkAudio = SoundManager.PlayIfNotPlaying("FireWallLoop", berserkAudio, parent.transform, useStdPitchOverride: false);
			return;
		}
		SetFullAutoStatus(basicSkill as MeleeAttackState, givenStatus: false);
		SetNegMeleeStatus(basicSkill as NegMeleeState, givenStatus: true);
		parent.overheadPrompt.HidePrompt(string.Empty);
		if (currentEffect != null)
		{
			currentEffect.Stop();
			if (currentEffect.gameObject != null)
			{
				UnityEngine.Object.Destroy(currentEffect.gameObject, 1.5f);
			}
		}
		PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter").Emit(4, currentPosition + Vector2.up * 2f, SmokeEmitter.SmokeSmallOverride);
		PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter").Emit(6, currentPosition + Vector2.up, SmokeEmitter.SmokeSmallOverride);
		if (berserkAudio != null)
		{
			berserkAudio.Stop();
		}
	}
	private void SetFullAutoStatus(MeleeAttackState givenSS, bool givenStatus)
	{
		givenSS?.fullAutoStat.Modify(fullAutoMod, givenStatus);
	}
	private void SetNegMeleeStatus(NegMeleeState givenNegState, bool givenStatus)
	{
		if (givenNegState != null)
		{
			givenNegState.allowCharge = givenStatus;
		}

		}
	}
}
