	public BubbleDash(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		isProjectileSkill = true;
		InitChargeSkillSettings(1, 0f, skillData, this);
	}
	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		SetSkillLevel((!IsEmpowered) ? 1 : 2);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		if (cooldownReady)
		{
			ApplyStopElement();
			atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.025f, 6);
			dropEmitter = PoolManager.GetPoolItem<WaterDropEmitter>();
		}
	}
	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (cooldownReady)
		{
			StopwatchState stopwatchState = ChaosStopwatch.CheckInterval(atkStopwatchID);
			if (stopwatchState == StopwatchState.Ready)
			{
				spawnPosition = parent.attackOriginTrans.position;
				dropEmitter.Emit(2, spawnPosition, WaterDropEmitter.MedWaterExplosionLightOverride);
				CreateBubbleProjectile(UnityEngine.Random.insideUnitCircle);
			}
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		if (cooldownReady)
		{
			spawnPosition = parent.attackOriginTrans.position;
			dropEmitter.Emit(5, spawnPosition, WaterDropEmitter.MedWaterExplosionLightOverride);
			for (int i = 0; i < 6; i++)
			{
				CreateBubbleProjectile(Globals.GetRotatedCircleVector(6, i, inputVector));
			}
		}
	}
	private void CreateBubbleProjectile(Vector2 givenVector)
	{
		currentBP = (BubbleProjectile)Projectile.CreateProjectile(parent, BubbleProjectile.Prefab, spawnPosition + givenVector * 0.5f);
		currentBP.isLarge = IsEmpowered;
		SetAttackInfo(currentBP.attack);
		currentBP.moveVector = givenVector;
		currentBP.moveSpeed = UnityEngine.Random.Range(3f, 5f);
		currentBP.flyTime = UnityEngine.Random.Range(1f, 1.375f);
		SoundManager.PlayWithDistAndSPR("BubblePop", spawnPosition);
	}
}
public class ChainedDash : BaseDashState
{
	public new static string staticID = "ChainedDash";
	private static int hitCount = 4;
	private ChaosQuickStopwatch chainStopwatch = new ChaosQuickStopwatch();
	private List<Transform> chainTransList = new List<Transform>();
	private Vector2 lastPosition;
	private ChainedDashOrb currentDO;
	private Vector2 chainPos;
	private Vector2 attackPos;
	public ChainedDash(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		InitChargeSkillSettings(3, 0f, skillData, this);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		if (cooldownReady)
		{
			chainStopwatch.SetDelay(1f + Mathf.Min(1f, (float)cooldownRef.chargeCount * 0.25f), stopCurrent: true, autoStart: true);
			chainTransList.RemoveNullValues();
			if (chainTransList.Count == 0)
			{
				CreateChain(parent.attackOriginTrans.position, givenStatus: false);
			}
			lastPosition = chainTransList[chainTransList.Count - 1].transform.position;
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		if (!cooldownReady)
		{
			return;
		}
		attackPos = parent.attackOriginTrans.position;
		CreateChain(attackPos);
		if (chainTransList[0] != null)
		{
			chainPos = chainTransList[0].transform.position;
			if (Entity.HasLineOfSight(chainPos, attackPos, 16f, ChaosCollisions.layerUpperWallAndObst) && cooldownRef.chargeCount == 0 && chainTransList.Count > 2)
			{
				lastPosition = attackPos;
				CreateChain(chainPos);
				chainStopwatch.IsRunning = false;
			}
		}
	}
	private void CreateChain(Vector2 givenPosition, bool givenStatus = true)
	{
		currentDO = ChaosInst<ChainedDashOrb>(ChainedDashOrb.Prefab, givenPosition);
		currentDO.chainStopwatch = chainStopwatch;
		currentDO.createAttack = givenStatus;
		currentDO.parentChainList = chainTransList;
		currentDO.parentID = parent.playerID;
		if (givenStatus)
		{
			currentDO.SetAttackVars(lastPosition, parent.skillCategory, skillID);
			ChainedDashOrb.SetHitCount(parent.playerID, Mathf.Min(20, hitCount + (IsEmpowered ? 2 : 0) + chainTransList.Count));
		}
		chainTransList.Add(currentDO.transform);
	}
}
