public class ChaosDashState : BaseDashState
{
	public new static string staticID = "ChaosDash";
	private static float teleportRange = 6f;
	private ChaosQuickStopwatch teleportStopwatch = new ChaosQuickStopwatch(0.125f);
	private float teleLerpValue;
	private Vector2 startPosition;
	private Vector2 endPosition;
	private Vector2 effectPosition;
	public ChaosDashState(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		showEffects = false;
		playSFX = false;
		empoweredStat.SetInitialBaseValue(newBaseVal: true);
	}
	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
	}
	public override void OnEnter()
	{
		base.OnEnter();
		startPosition = parent.transform.position;
		endPosition = startPosition + inputVector * teleportRange;
		if (!Globals.CheckCircle(endPosition, 0.25f, ChaosCollisions.layerAllWallAndObst) || Pathfinder.GetPath(Pathfinder.connectedNodeMap, startPosition, endPosition, ChaosCollisions.layerAllWallAndObst) == null)
		{
			endPosition = Globals.GetLinecastVector(startPosition, endPosition, ChaosCollisions.layerAllWallAndObst) - inputVector * 0.3f;
			if (Vector2.SqrMagnitude(endPosition - startPosition) < 1f)
			{
				endPosition = startPosition;
			}
		}
		SpawnTeleportEffect();
		string audioID = "ChaosBeamStart";
		Vector2? soundOrigin = startPosition;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.2f, standardPitchRange);
		teleportStopwatch.IsRunning = true;
		ToggleColliders(status: false);
	}
	public override void FixedUpdate()
	{
		if (!finishedDashing)
		{
			teleLerpValue = teleportStopwatch.TimePercentage;
			if (teleLerpValue >= 1f)
			{
				finishedDashing = true;
				parent.rigidbody2D.MovePosition(endPosition);
			}
			else
			{
				parent.rigidbody2D.MovePosition(Vector2.Lerp(startPosition, endPosition, teleLerpValue));
			}
		}
	}
	private void SpawnTeleportEffect(bool givenStart = true)
	{
		effectPosition = parent.attackOriginTrans.position;
		if (givenStart)
		{
			AnimEffect poolItem = PoolManager.GetPoolItem<AnimEffect>("ChaosPortal");
			Vector3 position = effectPosition;
			string animName = "Depart";
			Vector3? localEulerAngles = new Vector3(0f, 0f, UnityEngine.Random.Range(0f, 360f));
			poolItem.Play(position, animName, 0f, default, 1f, 1f, localEulerAngles);
		}
		else
		{
			PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(effectPosition, "Spawn");
			ChaosBurst.Spawn(effectPosition, 3);
		}
		SoundManager.PlayAudioWithDistance("Teleport", effectPosition, null, 24f, 0.075f);
	}
	public override void DashFinished()
	{
		base.DashFinished();
		SpawnTeleportEffect(givenStart: false);
		string audioID = "EnemyDead";
		Vector2? soundOrigin = parent.transform.position;
		float overridePitch = UnityEngine.Random.Range(1.1f, 1.2f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.35f, overridePitch);
		ToggleColliders(status: true);
	}
	private void ToggleColliders(bool status)
	{
		parent.hurtBoxObj.SetActive(status);
		parent.floorContact.SetActive(status);
		parent.fall.disableFallTransition = !status;
		if (status)
		{
			parent.Show();
		}
		else
		{
			parent.Hide();
		}
	}
}
