	public override void OnEnter()
	{
		BaseOnEnter();
		if (currentChargeObject != null)
		{
			UnityEngine.Object.Destroy(currentChargeObject);
		}
		currentChargeObject = UnityEngine.Object.Instantiate(chargeObjectPrefab, parent.attackOriginTrans.position, Quaternion.identity, parent.gameObject.transform);
		currentChargeObject.GetComponent<TrailRenderer>().sortingLayerName = "Effect";
		chargeAttackCollider = currentChargeObject.transform.Find("AttackBox").GetComponent<CircleCollider2D>();
		currentChargeObject.GetComponentInChildren<Attack>().SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
		SoundManager.PlayAudio("Haste");
		parent.movement.moveSpeedStat.AddMod(chargeSpeedMod);
		parent.Endure(ignoreKnockback: true, ignoreHurtState: true, faceHurtDirection: false);
		parent.StartCoroutine(ChargeOn());
	}
	public override void Update()
	{
		if (!skillIsActive)
		{
			ExitToSkillOrRunOrIdle();
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		skillIsActive = false;
		parent.movement.moveSpeedStat.RemoveMod(chargeSpeedMod.ID);
		parent.Endure();
		parent.hud.castBar.EndCast();
		UnityEngine.Object.Destroy(currentChargeObject);
	}
	private void SpawnSpike()
	{
		EarthFloorSpike component = UnityEngine.Object.Instantiate(spikePrefab, parent.transform.position + (Vector3)spikeSpawnVector.Randomize(0.25f) + (Vector3)parent.movement.moveVector * 0.5f, Quaternion.identity).GetComponent<EarthFloorSpike>();
		component.breakPrimaryParticleCount = 3;
		component.breakSeconaryParticleCount = 2;
		component.spawnParticleCount = 3;
		component.useFloorCollider = false;
		component.shakeOnSpawn = false;
		component.Activate(useAttackBox: false, useFloorCollider: false);
	}
	private IEnumerator ChargeOn()
	{
		parent.anim.PlayDirectional("Run" + parent.facingDirection);
		int hitCount = Mathf.CeilToInt(skillData.GetValue<float>("duration") / timeBetweenHits);
		parent.hud.castBar.StartCast(ChaosStopwatch.Begin((float)hitCount * timeBetweenHits), givenStatus: false);
		int durationStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, timeBetweenHits, hitCount);
		int minimumStopwatchID = ChaosStopwatch.Begin(1f);
		skillIsActive = true;
		int spikeSpawnTimerID = -1;
		float spikeSpawnTime = 0.125f;
		while (skillIsActive)
		{
			if (ChaosStopwatch.Check(minimumStopwatchID) && (parent.inputDevice.GetButtonDown("Skill" + skillSlot) || currentChargeObject == null))
			{
				skillIsActive = false;
			}
			switch (ChaosStopwatch.CheckInterval(durationStopwatchID))
			{
			case StopwatchState.Running:
				chargeAttackCollider.enabled = true;
				break;
			case StopwatchState.Ready:
				chargeAttackCollider.enabled = false;
				break;
			case StopwatchState.Done:
				skillIsActive = false;
				break;
			}
			if (ChaosStopwatch.Check(spikeSpawnTimerID))
			{
				SpawnSpike();
				spikeSpawnTimerID = ChaosStopwatch.Begin(spikeSpawnTime);
			}
			parent.movement.moveVector = GetInputVector(faceInputVector: false, useAimVector: false);
			parent.movement.MoveToMoveVector();
			parent.PlayAnimOnFaceDirChange("Run", parent.transform.position + (Vector3)parent.movement.moveVector);
			yield return null;
		}
	}
}
