			finalCancelThreshold = 0.7f;
			finalRunThreshold = 0.9f;
			finalExitThreshold = 1f;
		}
		else
		{
			maxComboCount = ((!repeatFinalHit) ? 2 : 3);
			finalCancelThreshold = normFinalCancel;
			finalRunThreshold = normFinalRun;
			finalExitThreshold = normFinalExit;
