	public override void OnEnter()
	{
		base.OnEnter();
		flipObjectForBackhand = true;
		base.ExecuteAttack();
		curEarthSpike = (EarthSpike)currentAttackObject;
		if (IsEmpowered)
		{
			curEarthSpike.isEmpowered = true;
		}
		spriteSorter = curEarthSpike.transform.GetComponentInChildren<SortSpriteLayer>();
		curFacingDir = Globals.GetPrimaryDirection(inputVector);
		if (parent.forehandAnimPlayed)
		{
			curEarthSpike.followScript.followTransform = parent.rightHandTransform;
			spriteSorter.yValueOffset = ((curFacingDir != FacingDirection.Up) ? (-1.5f) : 0f);
		}
		else
		{
			curEarthSpike.followScript.followTransform = parent.leftHandTransform;
		}
	}
	public override void ExecuteAttack()
	{
		curEarthSpike.anim.Play("Idle", -1, 0f);
		if (IsEmpowered)
		{
			curEarthSpike.anim.Play("IdleLarge", -1, 0f);
			curEarthSpike.attack.atkInfo.damage = Mathf.FloorToInt((float)curEarthSpike.attack.atkInfo.damage * 1.75f);
			curEarthSpike.attack.atkInfo.hitStunDurationModifier = 1.5f;
			curEarthSpike.attack.atkInfo.knockbackMultiplier = 20f;
		}
		curEarthSpike.followScript.enabled = false;
		curEarthSpike.transform.position = parent.attackOriginTrans.position + (Vector3)(inputVector * 0.3f);
		if (curFacingDir == FacingDirection.Right || curFacingDir == FacingDirection.Left)
		{
			flipObjectForBackhand = false;
			curEarthSpike.anim.PlayDirectional("Attack" + ((!parent.forehandAnimPlayed) ? "RightLH" : "RightRH") + ((!IsEmpowered) ? string.Empty : "Large"));
			if (curFacingDir == FacingDirection.Right)
			{
				Vector3 localScale = curEarthSpike.transform.localScale;
				localScale.x *= -1f;
				curEarthSpike.transform.localScale = localScale;
			}
			if (IsEmpowered)
			{
				CameraController.ShakeCamera(0.3f);
				PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(RockDebrisType.Default, 4, parent.attackOriginTrans.position + (Vector3)inputVector * 2f, RockDebrisEmitter.MedCircleExplosionOverride);
			}
			else
			{
				CameraController.ShakeCamera(0.17f);
				RockBurstDirectionalEffect poolItem = PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect");
				RockDebrisType debrisType = RockDebrisType.Default;
				int? particleCount = 5;
				Vector3? position = parent.attackOriginTrans.position;
				Vector3? localEulerAngles = Globals.GetRotationVector(inputVector);
				poolItem.EmitSingle(debrisType, particleCount, position, null, localEulerAngles);
			}
		}
		if (curFacingDir != FacingDirection.Up)
		{
			spriteSorter.yValueOffset = -1.5f;
		}
		parent.movement.EndMovement();
	}
	public override void OnExit()
	{
		base.OnExit();
		if (curEarthSpike != null)
		{
			curEarthSpike.EndAttack();
		}
		parent.movement.EndMovement();
	}
