public class FreezingLungeState : SkillState
{
	public new static string staticID = "FreezingLunge";
	private static float velocityMagnitude = 60f;
	private static int ultHitCount = 3;
	private FreezingLungeFist currentFL;
	private Vector2 startPosition;
	private float calcVelocity;
	private float initKbMultiplier;
	private bool dashInitiated;
	private bool attackActivated;
	private bool attackCompleted;
	private int ultCounter;
	private bool ultCompleted;
	private bool movementStopped;
	public override string OnEnterAnimStr => parent.ForehandAnimStr;
	public FreezingLungeState(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		isMovementSkill = true;
		isMeleeSkill = true;
		isHoldSkill = true;
		SetAnimTimes();
	}
	public override void OnEnter()
	{
		base.OnEnter();
		if (isUltimate)
		{
			ultCompleted = false;
			ultCounter = 0;
		}
		CreateFreezingLunge((!isUltimate) ? 1 : 3);
		parent.ToggleEnemyFloorCollisions(status: false);
		parent.TogglePreventFallCollider(status: false);
		SetInitVars(velocityMagnitude);
		parent.movement.moveVector = inputVector;
		parent.movement.dashVector = inputVector;
	}
	public override void HandleHoldButton()
	{
		if (!isUltimate || ultCounter <= 0 || !CancelToDash(enableButtonHeld: true))
		{
			holdReleased = parent.anim.AnimPlayed(animExecTime);
		}
	}
	public override void ExecuteSkill()
	{
		if (!dashInitiated)
		{
			dashInitiated = true;
			parent.rigidbody2D.velocity = inputVector * calcVelocity * parent.movement.dashDurationStat.CurrentValue * 8f;
			if (currentFL != null)
			{
				currentFL.StopEffects();
			}
		}
		if (!attackActivated)
		{
			attackActivated = true;
			if (currentFL != null)
			{
				currentFL.Execute();
			}
		}
		if (!attackCompleted)
		{
			if (parent.anim.AnimPlayed(cancelThreshold))
			{
				attackCompleted = true;
				if (currentFL != null)
				{
					currentFL.Reset();
					currentFL = null;
				}
				ChaosInst<SnowTrail>(SnowTrail.Prefab).EmitTrail(startPosition, parent.attackOriginTrans.position);
			}
			else if (currentFL != null)
			{
				currentFL.attack.atkInfo.knockbackMultiplier = initKbMultiplier * parent.rigidbody2D.velocity.magnitude * 0.025f;
			}
		}
		else if (isUltimate && !ultCompleted)
		{
			ultCounter++;
			switch (ultCounter)
			{
			case 1:
				parent.anim.PlayDirectional(parent.KickAnimStr, -1, 0.2f);
				CreateFreezingLunge(3);
				SetInitVars(velocityMagnitude * 0.5f);
				break;
			case 2:
				parent.anim.PlayDirectional(OnEnterAnimStr, -1, animStartTime);
				CreateFreezingLunge();
				SetInitVars(velocityMagnitude * 0.5f);
				initKbMultiplier *= 1.75f;
				break;
			case 3:
				ultCompleted = true;
				break;
			}
		}
		else
		{
			base.ExecuteSkill();
		}
	}
	public override void ConcludeSkill()
	{
		if (movementStopped)
		{
			base.ConcludeSkill();
		}
		else
		{
			fsm.ChangeState(SlideState.staticID);
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		parent.movement.EndMovement();
		parent.ToggleEnemyFloorCollisions();
		parent.TogglePreventFallCollider(status: true);
		CleanupFist();
	}
	private void CleanupFist()
	{
		if (currentFL != null)
		{
			Attack attack = currentFL.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			currentFL.Reset();
			currentFL = null;
		}
	}
	private void SetInitVars(float givenVelocity)
	{
		calcVelocity = givenVelocity;
		dashInitiated = false;
		attackActivated = false;
		attackCompleted = false;
		holdReleased = false;
	}
	private void CreateFreezingLunge(int givenLevel = 1)
	{
		CleanupFist();
		startPosition = parent.attackOriginTrans.position;
		currentFL = ChaosInst<FreezingLungeFist>(FreezingLungeFist.Prefab, startPosition - inputVector, Globals.GetRotationQuaternion(inputVector));
		currentFL.parentObject = parent.gameObject;
		currentFL.parentEntity = parent;
		currentFL.followTrans = parent.attackOriginTrans;
		currentFL.followOffset = -inputVector;
		currentFL.SetSkillInfo(parent.skillCategory, skillID, givenLevel, isUltimate);
		currentFL.attackVec = inputVector;
		currentFL.isEmpowered = IsEmpowered;
		currentFL.iceShardAttackLevel = 2;
		initKbMultiplier = Mathf.Max(1f, skillData.GetValue<float>(StatData.kbMultiStr, givenLevel));
		if (isUltimate && givenLevel != 1)
		{
			Attack attack = currentFL.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attack2 = currentFL.attack;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
		movementStopped = false;
	}
	private void OnTargetHit(Entity entity)
	{
		if (!movementStopped && ultCounter < ultHitCount && !(entity == null) && !(entity is Destructible))
		{
			movementStopped = true;
			parent.movement.EndMovement();
			parent.movement.MoveToMoveVector(6f);
		}
	}
}
public class FrostWingDash : BaseDashState
{
	public new static string staticID = "FrostWingDash";
	private static float[] spreadArray = new float[3] { 0.225f, 0.525f, 0.9f };
	private FrostWing frostWing;
	private FrostWingProjectile currentFW;
	private List<FrostWingProjectile> fwList = new List<FrostWingProjectile>();
	private Vector2 perpendVec;
	private int shotCount = 2;
	public FrostWingDash(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		isProjectileSkill = true;
		InitChargeSkillSettings(1, 0f, skillData, this);
	}
	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		shotCount = ((!IsEmpowered) ? 2 : 3);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		if (cooldownReady)
		{
			CreateWings(parent.attackOriginTrans.position);
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		if (cooldownReady)
		{
			ReleaseWings();
		}
		fwList.Clear();
	}
	private void CreateWings(Vector2 givenPosition)
	{
		perpendVec = Globals.GetPerpendicular(inputVector);
		for (int i = 0; i < shotCount; i++)
		{
			CreateFW(givenPosition, (perpendVec * spreadArray[i] - inputVector).normalized);
			CreateFW(givenPosition, (perpendVec * (0f - spreadArray[i]) - inputVector).normalized);
		}
		if (frostWing == null)
		{
			frostWing = ChaosInst<FrostWing>(FrostWing.Prefab, givenPosition, Globals.GetRotationQuaternion(inputVector), parent.playerObjTrans);
		}
		frostWing.transform.localEulerAngles = Globals.GetRotationVector(inputVector);
		frostWing.Initialize(parent, parent.attackOriginTrans);
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(12, givenPosition);
	}
	private void CreateFW(Vector2 givenPosition, Vector2 givenVector)
	{
		currentFW = (FrostWingProjectile)Projectile.CreateProjectile(parent, FrostWingProjectile.Prefab, givenPosition - givenVector, Globals.GetRotationQuaternion(givenVector));
		currentFW.InitFollow(parent.attackOriginTrans, givenVector * 0.5f);
		currentFW.attackBox.SetAttackInfo(parent.skillCategory, skillID);
		currentFW.attackBox.knockbackOverwriteVector = givenVector;
		currentFW.moveVector = givenVector;
		fwList.Add(currentFW);
	}
	private void ReleaseWings()
	{
		for (int num = fwList.Count - 1; num >= 0; num--)
		{
			fwList[num].Release();
		}
	}
}
public class HealState(string stateName, FSM parentFSM, Player parentEntity) : SkillState(stateName, parentFSM, parentEntity)
