	public IceDaggerBasic(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isBasic = true;
		isMeleeSkill = true;
		isMovementSkill = true;
		attackPrefab = IceDagger.Prefab;
		destroyAttackObjectOnExit = false;
		maxComboCount = 4;
		animStartTime = 0.12f;
		animExecTime = 0.2f;
		baseCancelThreshold = 0.3f;
