public class MultiShotState : ProjectileAttackState
{
	public new static string staticID = "MultiShot";
	private int calcSpread;
	private int calcCount;
	private int halfCount;
	private MultiShotArrow currentMS;
	private List<Projectile> arrowList = new List<Projectile>();
	private int ultStopwatchID;
	private bool ultFlip;
	public override string OnEnterAnimStr => parent.PBAoEAnimStr;

	public MultiShotState(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		SetAnimTimes(0f, 0.2f, 0f, 0.55f, 0.75f);
	}
	public override void OnEnter()
	{
		arrowList.Clear();
		base.OnEnter();
		calcCount = ((!IsEmpowered) ? 7 : 9);
		halfCount = (int)((float)calcCount * 0.5f);
		calcSpread = calcCount * 4 + 1;
		if (isUltimate)
		{
			ultStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.125f, 3);
			ultFlip = false;
		}
	}
	public override void ExecuteSkill()
	{
		if (isUltimate)
		{
			switch (ChaosStopwatch.CheckInterval(ultStopwatchID))
			{
			case StopwatchState.Ready:
				CreateMultiShotWave(parent.attackOriginTrans.position, (ultFlip ? Mathf.CeilToInt((float)calcSpread * 0.5f) : 0) - halfCount);
				ultFlip = !ultFlip;
				inputVector = -inputVector;
				calcCount--;
				halfCount = (int)((float)calcCount * 0.5f);
				calcSpread = (int)((float)calcSpread * 1.5f);
				if (calcSpread % 2 == 0)
				{
					calcSpread++;
				}
				break;
			case StopwatchState.Done:
				base.ExecuteSkill();
				break;
			}
		}
		else
		{
			base.ExecuteSkill();
			CreateMultiShotWave(parent.attackOriginTrans.position, -halfCount);
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		if (parent.fsm.nextState.name.Contains("Hurt") || parent.fsm.nextState.name.Contains("Dead"))
		{
			for (int num = arrowList.Count - 1; num >= 0; num--)
			{
				if (arrowList[num] != null)
				{
					(arrowList[num] as MultiShotArrow).CancelProjectile();
				}
			}
		}
		arrowList.Clear();
	}
	private void CreateMultiShotWave(Vector2 givenPosition, int givenOffset = 0)
	{
		for (int i = 0; i < calcCount; i++)
		{
			CreateMultiShotArrow(givenPosition, Globals.GetRotatedCircleVector(calcSpread, i + givenOffset, inputVector));
		}
		CameraController.ShakeCamera(0.25f);
	}
	private void CreateMultiShotArrow(Vector2 givenPosition, Vector2 givenVector)
	{
		currentMS = (MultiShotArrow)CreateProjectile(MultiShotArrow.Prefab, givenPosition + givenVector * 0.5f, Globals.GetRotationQuaternion(givenVector));
		currentMS.spawnTrail = true;
		arrowList.Add(currentMS);
		FireProjectile(currentMS, givenVector, setKnockbackVector: true, 0f, 0f, string.Empty);
	}
}
