public class ProjectileChainAttackState : ProjectileAttackState
{
	public float shotDelay = 0.125f;
	public int shotStopwatchID;
	public bool attackStarted;
	public bool firstAnim;
	public bool updateInput = true;
	private Vector2 checkAimVec;
	public ProjectileChainAttackState(string newName, FSM newFSM, Player newPlayer)
		: base(newName, newFSM, newPlayer)
	{
		disableStartCooldown = true;
		isHoldSkill = true;
		InitChargeSkillSettings(skillData.GetValue<int>(StatData.spawnStr), 0f, skillData, this);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		UpdateCDCounter();
		attackStarted = false;
		firstAnim = true;
	}
	public override void HandleHoldButton()
	{
		if (!StartAttack())
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(shotStopwatchID))
		{
		case StopwatchState.Ready:
			if (firstAnim)
			{
				firstAnim = false;
				AnnounceSkillExecuteEvent();
			}
			else if (updateInput)
			{
				checkAimVec = GetInputVector(faceInputVector: false, useAimVector: true, ignoreZero: false);
				if (checkAimVec != Vector2.zero)
				{
					inputVector = GetInputVector(faceInputVector: true, useAimVector: true, ignoreZero: false);
				}
				parent.anim.PlayDirectional(OnHoldAnimStr, -1, animExecTime);
			}
			if (cooldownRef.chargeCount > 0)
			{
				cooldownRef.chargeCount--;
			}
			if (!cooldownRef.IsCharging)
			{
				UpdateCDCounter();
			}
			FireChainProjectile();
			break;
		case StopwatchState.Done:
			skillExecuted = true;
			break;
		}
		CancelToDash();
	}
	public override void OnExit()
	{
		base.OnExit();
		StartCooldownTimer(-1f, expendCharge: false);
		ChaosStopwatch.Stop(shotStopwatchID);
	}
	public virtual void UpdateCDCounter()
	{
		StartCooldownTimer(-1f, expendCharge: false);
		ChaosStopwatch.Pause(cooldownRef.remainingTimeStopwatchID);
	}
	public virtual bool StartAttack()
	{
		if (!attackStarted)
		{
			if (!parent.anim.AnimPlayed(animExecTime))
			{
				return false;
			}
			attackStarted = true;
			shotStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, shotDelay, cooldownRef.chargeCount);
		}
		return true;
	}

	}
	public virtual void FireChainProjectile()
	{
	}
}
public class ProjectileChargeAttackState(string newName, FSM newFSM, Player newPlayer) : ProjectileHoldAttackState(newName, newFSM, newPlayer)
{
	public bool useCastBar = true;
	public int maxCharge = 10;
	public int minCharge = 5;
	public float chargeTime = 0.2f;
	public float calcChargeTime;
	public int chargeStopwatchID;
	public bool fullyCharged;
	public int postStopwatchID;
	public AudioSource chargeAudioSource;
	public string chargeAudioID = string.Empty;
	public bool ignoreAudioIsPlaying;
	public bool lowerChargeTimeOnEmpower = true;
	public override void OnEnter()
	{
		base.OnEnter();
		calcChargeTime = ((!lowerChargeTimeOnEmpower || !IsEmpowered) ? chargeTime : (chargeTime * 0.5f));
		fullyCharged = maxCharge - minCharge <= 0;
		if (useCastBar && !fullyCharged)
		{
			parent.hud.castBar.StartCast(ChaosStopwatch.Begin(calcChargeTime * (float)(maxCharge - minCharge)), givenStatus: true);
		}
		PlayChargeEffects();
	}
	public override void HandleHoldButton()
	{
		base.HandleHoldButton();
		if (!fullyCharged)
		{
			switch (ChaosStopwatch.CheckInterval(chargeStopwatchID))
			{
			case StopwatchState.Ready:
				PlayChargeEffects();
				AddProjectileCharge();
				break;
			case StopwatchState.Done:
				fullyCharged = true;
				postStopwatchID = ChaosStopwatch.Begin(calcChargeTime);
				break;
			}
		}
		else
		{
			HandlePostStopwatch();
		}
	}
	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		if (useCastBar)
		{
			parent.hud.castBar.EndCast();
		}
		StopChargeAudio();
	}
	public override void OnExit()
	{
		base.OnExit();
		if (useCastBar)
		{
			parent.hud.castBar.EndCast();
		}
		StopChargeAudio();
	}
	public override Projectile CreateHoldProjectile()
	{
		chargeStopwatchID = ChaosStopwatch.Begin(calcChargeTime, useInterval: true, calcChargeTime, maxCharge - minCharge);
		return base.CreateHoldProjectile();
	}
	public virtual void HandlePostStopwatch()
	{
		if (ChaosStopwatch.Check(postStopwatchID))
		{
			postStopwatchID = ChaosStopwatch.Begin(calcChargeTime);
			PlayChargeEffects();
		}
	}
	public virtual void PlayChargeEffects()
	{
		if (!(chargeAudioID == string.Empty))
		{
			if (ignoreAudioIsPlaying)
			{
				StopChargeAudio();
			}
			if (currentProjectile != null)
			{
			}
		}
	}
	public void StopChargeAudio()
	{
		if (chargeAudioSource != null)
		{
			chargeAudioSource.Stop();
		}
	}
	public virtual void AddProjectileCharge()
	{
	}
}
public class ProjectileHoldAttackState : ProjectileAttackState
{
	public GameObject projectilePrefab;
	public Projectile currentProjectile;
	public float holdRange = 1f;
	public string fireAudioID = string.Empty;
	public bool updateRotation;
	public bool recenterOnRelease = true;
	public override string OnEnterAnimStr => parent.ChargeAnimStr;
	public override string OnHoldAnimStr => parent.ChargeAnimStr;
	public virtual Vector2 HoldPosition => (Vector2)parent.attackOriginTrans.position - Entity.GetFacingDirectionVector(parent.facingDirection) * holdRange;
	public ProjectileHoldAttackState(string newName, FSM newFSM, Player newPlayer)
		: base(newName, newFSM, newPlayer)
	{
		disableStartCooldown = true;
		isHoldSkill = true;
	}
	public override void OnEnter()
	{
		base.OnEnter();
		CreateHoldProjectile();
	}
	public override void Update()
	{
		if (currentProjectile == null)
		{
			ExitToSkillOrRunOrIdle();
		}
		else
		{
			base.Update();
		}
	}
	public override void HandleHoldButton()
	{
		base.HandleHoldButton();
		if (!(currentProjectile == null))
		{
			currentProjectile.RefreshFlightTime();
			currentProjectile.transform.position = HoldPosition;
			if (updateRotation)
			{
				currentProjectile.transform.localEulerAngles = Globals.GetRotationVector(inputVector);
			}
		}
	}
	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		StartCooldownTimer();
		parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animExecTime);
		if (!(currentProjectile == null))
		{
			if (updateRotation)
			{
				currentProjectile.isPointedAtMoveVector = false;
			}
			if (recenterOnRelease)
			{
				currentProjectile.transform.position = parent.attackOriginTrans.position;
			}
			Projectile projectile = currentProjectile;
			Vector2 moveVector = inputVector;
			string audioString = fireAudioID;
			FireProjectile(projectile, moveVector, setKnockbackVector: true, 0f, 0f, audioString);
