public class ShootEarthShotgun : ProjectileAttackState
{
	public new static string staticID = "ShootEarthShotgun";
	private GameObject prefab;
	private bool firstFrame;
	private float selfCancelThreshold;
	private Vector2 attackVector;
	private int shotCount = 3;
	private float shotRange = 7f;
	private float shotSpread = 2f;
	private float shotDelay = 0.2f;
	private float pelletSpeed = 30f;
	private float pelletFlyTime = 0.2f;
	private int pelletCount = 8;
	private bool shotGunFired;
	private Vector2 pelletOffset;
	private Projectile pellet;
	public ShootEarthShotgun(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		cancelThreshold = 0.3f;
		allowSelfTransition = true;
		selfCancelThreshold = 0.2f;
		prefab = GetPrefabResource("EarthPellet");
		InitChargeSkillSettings(shotCount, shotDelay, skillData, this);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		allowSelfTransition = false;
		SetRepeatLock();
		attackVector = GetInputVector();
		parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animStartTime);
		firstFrame = true;
		shotGunFired = false;
	}
	public override void Update()
	{
		if (firstFrame)
		{
			firstFrame = false;
			return;
		}
		UpdateRepeatLock(string.Empty);
		if (!shotGunFired)
		{
			shotGunFired = true;
			ShootShotgun();
			return;
		}
		if (!allowSelfTransition && parent.anim.AnimPlayed(selfCancelThreshold))
		{
			allowSelfTransition = true;
		}
		ExitToSkillOrRunOrIdle();
	}
	private void ShootShotgun()
	{
		pelletOffset = attackVector * shotRange;
		FirePellet((pelletOffset + new Vector2(attackVector.y, 0f - attackVector.x) * shotSpread).normalized);
		FirePellet((pelletOffset + new Vector2(0f - attackVector.y, attackVector.x) * shotSpread).normalized);
		for (int i = 0; i < pelletCount - 2; i++)
		{
			FirePellet((pelletOffset + new Vector2(UnityEngine.Random.Range(-1f, 1f), UnityEngine.Random.Range(-1f, 1f)) * shotSpread).normalized);
		}
	}

	}
	private void FirePellet(Vector2 fireVector)
	{
		pellet = CreateProjectile(prefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(attackVector));
		Projectile projectile = pellet;
		float newMoveSpeed = pelletSpeed;
		FireProjectile(projectile, fireVector, setKnockbackVector: true, newMoveSpeed, pelletFlyTime, string.Empty);
	}
}
public class ShootFireArc : ProjectileChainAttackState
{
	public new static string staticID = "ShootFireArc";
	private NumVarStatMod empMod;
	private FireArc currentFA;
	private Vector2 spawnPosition;
	private Vector2 perpendVec;
	private bool currentArcStatus;
	private FireBurst fbEmitter;
	public override string OnHoldAnimStr => parent.NextHandAnimStr;
	public ShootFireArc(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		SetAnimTimes(0.1f, 0.2f, 0.3f, 0.55f, 0.75f);
		shotDelay = 0.1f;
		empMod = new NumVarStatMod(skillID, 0.25f, 10, VarStatModType.Multiplicative);
	}
	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		cooldownRef.maxChargeStat.Modify(empMod, IsEmpowered);
		cooldownRef.chargeCount = Mathf.Min(cooldownRef.MaxChargeCount, cooldownRef.chargeCount);
		StartCooldownTimer(-1f, expendCharge: false);
	}
	public override void OnEnter()
	{
		SetUltVars(isUltimate);
		base.OnEnter();
		CameraController.ShakeCamera(0.25f);
		fbEmitter = PoolManager.GetPoolItem<FireBurst>();
	}
	public override void FireChainProjectile()
	{
		currentArcStatus = ((!parent.isFacingRight) ? parent.playForehandAnim : (!parent.playForehandAnim));
		spawnPosition = parent.attackOriginTrans.position;
		FireFireArc(spawnPosition, inputVector, currentArcStatus);
		if (isUltimate)
		{
			spawnPosition -= inputVector * 0.5f;
			perpendVec = Globals.GetPerpendicular(inputVector);
			FireFireArc(spawnPosition + perpendVec, inputVector + perpendVec * 0.08f, currentArcStatus);
			FireFireArc(spawnPosition - perpendVec, inputVector - perpendVec * 0.08f, currentArcStatus);
		}
		else if (IsEmpowered && cooldownRef.chargeCount > 0)
		{
			FireFireArc(spawnPosition, inputVector, !currentArcStatus);
			cooldownRef.chargeCount--;
		}
		if (cooldownRef.chargeCount == 0)
		{
			ChaosStopwatch.Stop(shotStopwatchID);
		}
	}
	private void FireFireArc(Vector2 givenPosition, Vector2 givenVector, bool positiveArc)
	{
		currentFA = (FireArc)CreateProjectile(FireArc.Prefab, givenPosition + givenVector + UnityEngine.Random.insideUnitCircle * 0.5f, Globals.GetRotationQuaternion(givenVector));
		currentFA.targetVector = givenVector;
		currentFA.attackBox.knockbackOverwriteVector = givenVector;
		currentFA.positiveApproach = positiveArc;
		currentFA.arcRange = UnityEngine.Random.Range(3f, 8f);
		currentFA.flyTime = 0.75f;
		if (fbEmitter != null)
		{
			FireBurst fireBurst = fbEmitter;
			int? particleCount = 3;
			Vector3? position = givenPosition;
			Vector3? localEulerAngles = Globals.GetRotationVector(givenVector);
			fireBurst.EmitSingle(particleCount, position, null, localEulerAngles);
		}
	}
	private void SetUltVars(bool givenStatus)
	{
		if (givenStatus)
		{
			cooldownRef.Reset();
			shotDelay = 0.08f;
			animStartTime = 0.25f;
		}
		else
		{
			shotDelay = 0.1f;
			animStartTime = 0.1f;
		}
	}
}
public class ShootFireball : ProjectileAttackState
{
	public new static string staticID = "ShootFireball";
	private Fireball currentFB;
	private NumVarStatMod kbMod;
	private int ultStopwatchID;
	private int ultCount = 2;
	private int ultCounter;
	private float ultInterval = 0.2f;
	private bool ultFinished;
	private Vector2 checkAimVec;
	public override string OnEnterAnimStr => parent.ForehandAnimStr;
	public ShootFireball(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		SetAnimTimes(0.2f, 0.2f, 0.3f, 0.55f, 0.75f);
		kbMod = new NumVarStatMod(staticID, 0.25f, 10, VarStatModType.Multiplicative);
	}
	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		skillData.ModifyMod(StatData.kbMultiStr, kbMod, IsEmpowered);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		CreateFireball(parent.rightHandTransform.position);
	}
	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		CameraController.ShakeCamera(0.25f);
		ReleaseFireball();
		if (isUltimate)
		{
			ultFinished = false;
			ultCounter = 1;
			ultStopwatchID = ChaosStopwatch.Begin(ultInterval, useInterval: true, ultInterval, ultCount);
		}
	}
	public override void ConcludeSkill()
	{
		if (isUltimate && !ultFinished)
		{
			if (CancelToDash())
			{
				return;
			}
			switch (ChaosStopwatch.CheckInterval(ultStopwatchID))
			{
			case StopwatchState.Ready:
				checkAimVec = GetInputVector(faceInputVector: false, useAimVector: true, ignoreZero: false);
				if (checkAimVec != Vector2.zero)
				{
					inputVector = GetInputVector(faceInputVector: true, useAimVector: true, ignoreZero: false);
				}
				parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animExecTime);
				CreateFireball(parent.attackOriginTrans.position);
				ReleaseFireball();
				ultCounter++;
				break;
			case StopwatchState.Done:
				ultFinished = true;
				break;
			}
		}
		else
		{
			ExitToSkillOrRunOrIdle();
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		if (!skillExecuted && currentFB != null)
		{
			currentFB.BaseResetOnly();
		}
	}
	public void CreateFireball(Vector2 givenLocation)
	{
		currentLevel = ((!isUltimate) ? 1 : ((ultCounter != ultCount) ? 2 : 3));
		currentFB = (Fireball)CreateProjectile(Fireball.Prefab, givenLocation, Globals.GetRotationQuaternion(inputVector));
		currentFB.attackBox.gameObject.SetActive(value: false);
		currentFB.wallCollider.enabled = false;
		currentFB.isEmpowered = IsEmpowered;
	}
	public void ReleaseFireball()
	{
		if (!(currentFB == null))
		{
			currentFB.transform.position = parent.attackOriginTrans.position;
			FireProjectile(currentFB, inputVector, setKnockbackVector: true, 0f, 0f, string.Empty);
			currentFB.attackBox.gameObject.SetActive(value: true);
			currentFB.wallCollider.enabled = true;
			currentFB.autoEmitSmoke = true;
			FireBurst poolItem = PoolManager.GetPoolItem<FireBurst>();
			int? particleCount = 3;
			Vector3? position = parent.attackOriginTrans.position;
			Vector3? localEulerAngles = Globals.GetRotationVector(inputVector);
			poolItem.EmitSingle(particleCount, position, null, localEulerAngles);
		}
	}
}
