public class ShootLaserBeamState : SkillState
{
	public new static string staticID = "ShootLaserBeam";
	private GameObject currentBeam;
	private int originalDamage;
	private bool laserFired;
	private int shootStopwatchID;
	private float chargingDuration = 0.25f;
	public ShootLaserBeamState(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		cancelThreshold = 0.75f;
		exitThreshold = 1.2f;
		allowSelfTransition = true;
		disableStartCooldown = true;
		InitChargeSkillSettings(5, 0f, skillData, this);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		inputVector = GetInputVector();
		currentBeam = UnityEngine.Object.Instantiate(LaserBeam.Prefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(inputVector));
		int chargeCount = cooldownRef.chargeCount;
		int maxChargeCount = cooldownRef.MaxChargeCount;
		chargeCount *= chargeCount;
		maxChargeCount *= maxChargeCount;
		currentBeam.transform.localScale *= 0.7f * ((float)chargeCount / (float)maxChargeCount) + 0.3f;
		originalDamage = skillData.GetValue<int>("damage");
		int num = Mathf.CeilToInt(chargeCount + 5);
		skillData.SetValue("damage", originalDamage + num);
		currentBeam.GetComponentInChildren<Attack>().SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
		cooldownRef.chargeCount = 0;
		laserFired = false;
		shootStopwatchID = ChaosStopwatch.Begin(chargingDuration);
	}
	public override void Update()
	{
		if (!laserFired)
		{
			inputVector = GetInputVector();
			parent.anim.PlayDirectional(forehandAnimStr + parent.facingDirection, -1, 0.2f);
			StartCooldownTimer();
			currentBeam.transform.localEulerAngles = Globals.GetRotationVector(inputVector);
			if (ChaosStopwatch.Check(shootStopwatchID))
			{
				laserFired = true;
				if (currentBeam != null)
				{
					currentBeam.GetComponent<Animator>().Play("Shoot");
				}
			}
		}
		ExitToSkillOrRunOrIdle();
	}
	public override void OnExit()
	{
		base.OnExit();
		if (currentBeam != null)
		{
			UnityEngine.Object.Destroy(currentBeam);
		}
		skillData.SetValue("damage", originalDamage);
	}
}
public class ShootVacuumShot : ProjectileAttackState
{
	public new static string staticID = "ShootVacuumShot";
	private VacuumShot currentVS;
	private Vector2 spawnPosition;
	private Vector2 perpendVec;
	private Vector2 tempOffset;
	private int ultWaveCounter;
	private bool ultFired;
	private ChaosQuickStopwatch delayStopwatch = new ChaosQuickStopwatch(0.125f);
	public ShootVacuumShot(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		startCooldownOnEnter = false;
		useSmartCD = true;
		SetAnimTimes(0.2f, 0.2f, 0.3f, 0.6f, 0.75f);
		InitChargeSkillSettings(2, 0.125f, skillData, this);
	}
	public override void OnEnter()
	{
		if (isUltimate)
		{
			cooldownRef.chargeCount = 0;
			ultWaveCounter = 1;
			ultFired = false;
		}
		base.OnEnter();
		parent.ToggleEnemyFloorCollisions(status: false);
	}
	public override void ExecuteSkill()
	{
		spawnPosition = parent.attackOriginTrans.position;
		PlayShootEffects();
		if (isUltimate)
		{
			if (!ultFired)
			{
				ultFired = true;
				CreateVacuumWall();
				delayStopwatch.IsRunning = true;
			}
			CancelToDash();
			if (ultWaveCounter < 4)
			{
				if (!delayStopwatch.IsRunning)
				{
					ultWaveCounter++;
					ultFired = false;
					parent.anim.PlayDirectional(OnEnterAnimStr, -1, animStartTime);
				}
				return;
			}
		}
		else
		{
			CreateVacuumShot(spawnPosition + inputVector * 0.2f);
		}
		base.ExecuteSkill();
		StartCooldownTimer();
	}
	private void CreateVacuumWall()
	{
		perpendVec = Globals.GetPerpendicular(inputVector) * 0.75f;
		spawnPosition += inputVector * 0.25f;
		CreateVacuumShot(spawnPosition);
		for (int i = 1; i < 7; i += 2)
		{
			spawnPosition -= inputVector * 0.125f;
			tempOffset = (i + 1) * perpendVec;
			CreateVacuumShot(spawnPosition + tempOffset);
			CreateVacuumShot(spawnPosition - tempOffset);
		}
	}
	private void CreateVacuumShot(Vector2 givenPosition)
	{
		if (Globals.CheckCircle(givenPosition, 0.25f, ChaosCollisions.layerUpperWall))
		{
			currentVS = (VacuumShot)CreateProjectile(VacuumShot.Prefab, givenPosition + inputVector, Globals.GetRotationQuaternion(inputVector));
			currentVS.isEmpowered = IsEmpowered;
			FireProjectile(currentVS, inputVector, setKnockbackVector: true, 0f, 0f, string.Empty);
			if (isUltimate)
			{
				currentVS.moveSpeed *= 1.125f;
			}
			PoolManager.GetPoolItem<DashAirBurst>().Burst(currentVS.transform.position, inputVector, useOffset: false);
		}
	}
	private void PlayShootEffects()
	{
		CameraController.ShakeCamera(0.25f);
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 15;
		float z = Globals.GetRotationVector(-inputVector).z;
		Vector3? emitPosition = parent.transform.position + (Vector3)inputVector * 0.5f;
		poolItem.EmitDirBurst(particleCount, z, 12f, -1f, 0.4f, emitPosition);
	}
	public override void OnExit()
	{
		base.OnExit();
		parent.ToggleEnemyFloorCollisions();
	}
}
