public class SummonHomingMissilesState : ProjectileAttackState
{
	public new static string staticID = "SummonHomingMissiles";
	private HomingMissile currentHM;
	private int spawnCount = 7;
	private float duration = 2.75f;
	private float homingRadius = 5f;
	private List<HomingMissile> hmList = new List<HomingMissile>();
	private ChaosQuickStopwatch durationStopwatch = new ChaosQuickStopwatch(3f);
	private ChaosQuickStopwatch intervalStopwatch = new ChaosQuickStopwatch(0.125f);
	private Vector2 currentPosition;
	private Vector2 seedVector;
	private const int SeedMax = 6;
	private int seedValue;
	public override string OnEnterAnimStr => parent.PBAoEAnimStr;
	public SummonHomingMissilesState(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		SetAnimTimes(0.1f);
	}
	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		if (IsEmpowered)
		{
			spawnCount = 10;
			duration = 4f;
		}
		else
		{
			spawnCount = 7;
			duration = 2.75f;
		}
	}
	public override void OnEnter()
	{
		base.OnEnter();
		homingRadius = ((!isUltimate) ? 5f : 7f);
	}
	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		CameraController.ShakeCamera(0.25f);
		if (isUltimate)
		{
			parent.StartCoroutine(CreateHomingCloud());
		}
		else
		{
			CreateHomingRing(spawnCount);

			CreateHomingRing(spawnCount);
		}
	}
	private void CreateHomingRing(int givenCount, bool addToList = false)
	{
		currentPosition = parent.attackOriginTrans.position;
		seedVector = UnityEngine.Random.insideUnitCircle.normalized;
		for (int i = 0; i < givenCount; i++)
		{
			CreateHomingMissile(currentPosition, Globals.GetRotatedCircleVector(givenCount, i, seedVector), addToList);
		}
	}
	private void CreateHomingMissile(Vector2 givenPosition, Vector2 givenVector, bool addToList = false)
	{
		currentHM = (HomingMissile)CreateProjectile(HomingMissile.Prefab, givenPosition + givenVector);
		currentHM.InitOrbitVars(givenVector, duration, homingRadius);
		if (addToList)
		{
			hmList.Add(currentHM);
			currentHM.attackBox.atkInfo.isUltimate = true;
		}
	}
	private void CleanUpList()
	{
		for (int num = hmList.Count - 1; num >= 0; num--)
		{
			if (hmList[num] == null || !hmList[num].orbitMode)
			{
				hmList.RemoveAt(num);
			}
		}
	}
	private void ResetList()
	{
		for (int num = hmList.Count - 1; num >= 0; num--)
		{
			if (hmList[num] != null)
			{
				hmList[num].ResetProjectile();
			}
		}
		hmList.Clear();
	}
	private IEnumerator CreateHomingCloud()
	{
		parent.hud.castBar.EndCast();
		yield return null;
		if (durationStopwatch.IsRunning)
		{
			durationStopwatch.IsRunning = true;
			parent.hud.castBar.StartCast(durationStopwatch.ID, givenStatus: false);
			CreateHomingRing(spawnCount, addToList: true);
			yield break;
		}
		ResetList();
		yield return null;
		durationStopwatch.IsRunning = true;
		parent.hud.castBar.StartCast(durationStopwatch.ID, givenStatus: false);
		CreateHomingRing(spawnCount, addToList: true);
		seedValue = UnityEngine.Random.Range(0, 6);
		while (durationStopwatch.IsRunning)
		{
			if (!intervalStopwatch.IsRunning)
			{
				intervalStopwatch.IsRunning = true;
				seedValue++;
				CleanUpList();
				if (hmList.Count < spawnCount)
				{
					CreateHomingMissile(parent.attackOriginTrans.position, Globals.GetCirclePositionVector(6, seedValue), addToList: true);
				}
			}
			yield return null;
		}
		parent.hud.castBar.EndCast();
	}
}
