		if (HandleWindup())
		{
			return;
		}
		if (!gustFistStarted)
		{
			gustFistStarted = true;
			EndAllAttacks();
			parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, 0.15f);
			parent.movement.moveSpeedStat.AddMod(finalAtkMoveMod);
			parent.movement.moveVector = targetVector;
			parent.movement.MoveToMoveVector();
			return;
		}
		if (!gustFistCreated)
		{
			if (!parent.anim.AnimPlayed(animExecTime))
			{
				return;
			}
			gustFistCreated = true;
			parent.movement.EndMovement();
			CreateGustFist(parent.attackOriginTrans.position, targetVector);
		}
		base.ExecuteSkill();
	}
	public override void OnExit()
	{
		base.OnExit();
		parent.ToggleEnemyFloorCollisions();
		parent.movement.moveSpeedStat.RemoveMod(staticID);
		parent.hud.castBar.EndCast();
		parent.overheadPrompt.HidePrompt("ShakeAnalog");
		EndAllAttacks();
	}
	private bool HandleWindup()
	{
		if (!tumbleFistCreated)
		{
			tumbleFistCreated = true;
			atkPosition = parent.attackOriginTrans.position;
			if (isUltimate)
			{
				for (int i = 0; i < 4; i++)
				{
					ultFists[i] = CreateTumbleFist(atkPosition + ultHoldRange * Globals.GetRotatedCircleVector(5, i + 1, targetVector));
					ultFists[i].light.enabled = false;
				}
			}
			CreateTumbleFist(atkPosition + targetVector * holdRange);
			CameraController.ShakeCamera(0.25f);
			parent.overheadPrompt.PlayShakeAnalog(2f);
			durationStopwatchID = ChaosStopwatch.Begin((float)(calcCount - 1) * hitInterval);
			parent.hud.castBar.StartCast(durationStopwatchID, givenStatus: false);
		}
		if (!gustFistStarted)
		{
			parent.anim.PlayDirectional(parent.BackhandAnimStr, -1, animHoldTime);
		}
		if (CancelToDash())
		{
			return true;
		}
		return TumbleFistActive;
	}
	private void UpdateTargetVector()
	{
		inputVector = GetInputVector(faceInputVector: false, useAimVector: true, ignoreZero: false);
		if (!(inputVector == Vector2.zero))
		{
			targetVector = (targetVector + inputVector * 5f * Time.fixedDeltaTime).normalized;
			parent.FaceTarget(targetVector + (Vector2)parent.transform.position);
		}
	}
	private TumbleFist CreateTumbleFist(Vector2 givenPosition)
	{
		currentTF = ChaosInst<TumbleFist>(TumbleFist.Prefab, givenPosition);
		currentTF.attack.SetAttackInfo(parent.skillCategory, skillID, 1, isUltimate);
		currentTF.hitCount = calcCount;
		currentTF.hitInterval = hitInterval;
		return currentTF;
	}
	private void CreateGustFist(Vector2 givenPosition, Vector2 givenVector)
	{
		currentAtk = ChaosInst<Attack>(Attack.CirclePrefab, givenPosition + givenVector);
		Attack attack = currentAtk;
		string skillCategory = parent.skillCategory;
		string newSkillID = skillID;
		int newSkillLevel;
		if (isUltimate)
		{
			newSkillLevel = 4;
		}
		else
		{
			newSkillLevel = ((!IsEmpowered) ? 2 : 3);
		}
		attack.SetAttackInfo(skillCategory, newSkillID, newSkillLevel, isUltimate);
		currentAtk.knockbackOverwriteVector = givenVector;
		currentAtk.transform.localScale *= 3f;
		UnityEngine.Object.Destroy(currentAtk.gameObject, 0.125f);
	}
	private void EndAllAttacks()
	{
		if (TumbleFistActive)
		{
			currentTF.StopAttack();
		}
		if (!isUltimate)
		{
			return;
		}
		for (int i = 0; i < 4; i++)
		{
			if (ultFists[i] != null && !ultFists[i].attackCompleted)
			{
				ultFists[i].StopAttack();
			}
		}
	}
}
