	public class UseAeroRipple : ProjectileAttackState
	{
		public new static string staticID = "UseAeroRipple";
		private static float flyRange = 3.5f;
		private static float[] scaleArr = new float[5] { 1f, 0.875f, 0.75f, 0.625f, 0.5f };
		private static float[] speedArr = new float[5] { 16f, 14f, 12f, 10f, 8f };
		private static float[] timeArr;
		private int rippleCount = 3;
		private Vector2 spawnPosition;
		private AeroRipple currentAR;
		private Vector2 ultVector;
		private int ultStopwatchID;
		private bool ultStarted;
		private bool ultBlasted;
		public UseAeroRipple(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			allowSelfTransition = true;
			allowRepeating = true;
			SetAnimTimes(0.15f, 0.2f, 0.25f, 0.5f, 0.7f);
			InitChargeSkillSettings(2, 0f, skillData, this);
			if (timeArr == null)
			{
				timeArr = new float[speedArr.Length];
				for (int i = 0; i < speedArr.Length; i++)
				{
					timeArr[i] = flyRange / speedArr[i];
				}
			}
		}
		public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			base.SetEmpowered(givenStatus, givenMod);
			rippleCount = ((!IsEmpowered) ? 3 : 4);
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.ToggleEnemyFloorCollisions(status: false);
			parent.movement.EndMovement();
			CameraController.ShakeCamera(0.125f);
			if (isUltimate)
			{
				StartCooldownTimer(99f);
				allowSelfTransition = false;
				allowRepeating = false;
				ultStarted = false;
				ultBlasted = false;
			}
			else
			{
				allowSelfTransition = true;
				allowRepeating = true;
				SetSkillLevel(1);
			}
		}
		public override void ExecuteSkill()
		{
			if (isUltimate)
			{
				if (!ultStarted)
				{
					ultStarted = true;
					ultStopwatchID = ChaosStopwatch.Begin(0.25f, useInterval: true, 0.25f, 2);
					CreateRippleCircle(2, 4f, givenOffset: false, givenOut: false);
					return;
				}
				switch (ChaosStopwatch.CheckInterval(ultStopwatchID))
				{
				case StopwatchState.Ready:
					if (!ultBlasted)
					{
						ultBlasted = true;
						CreateRippleCircle(3, 0f, givenOffset: true, givenOut: true);
						parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animExecTime);
						CameraController.ShakeCamera(0.2f);
					}
					else
					{
						CreateRippleCircle(2, 1.5f, givenOffset: false, givenOut: true);
						parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, animExecTime);
						CameraController.ShakeCamera(0.3f);
					}
					break;
				case StopwatchState.Done:
					base.ExecuteSkill();
					break;
				}
				CancelToDash();
			}
			else
			{
				base.ExecuteSkill();
				spawnPosition = parent.attackOriginTrans.position;
				CreateRipples(spawnPosition + inputVector * flyRange, -inputVector, rippleCount);
				PlayAudio(spawnPosition, useBlast: false);
			}
		}
		public override void OnExit()
		{
			base.OnExit();
			parent.ToggleEnemyFloorCollisions();
		}
		private void CreateRippleCircle(int givenLevel, float givenRange, bool givenOffset, bool givenOut)
		{
			SetSkillLevel(givenLevel);
			spawnPosition = parent.attackOriginTrans.position;
			for (int i = (givenOffset ? 1 : 0); i < 12; i += 2)
			{
				ultVector = Globals.GetRotatedCircleVector(12, i, inputVector);
				CreateRipples(spawnPosition + ultVector * givenRange, (!givenOut) ? (-ultVector) : ultVector, 3);
			}
			PlayAudio(spawnPosition);
		}
		private void CreateRipples(Vector2 givenPosition, Vector2 givenVector, int givenCount)
		{
			for (int i = 0; i < givenCount; i++)
			{
				CreateAeroRipple(givenPosition, givenVector, i);
			}
		}
		private void CreateAeroRipple(Vector2 givenPosition, Vector2 givenVector, int givenIndex)
		{
			currentAR = (AeroRipple)CreateProjectile(AeroRipple.Prefab, givenPosition - givenVector * 0.2f * givenIndex, Globals.GetRotationQuaternion(givenVector));
			currentAR.transform.localScale = new Vector3(scaleArr[givenIndex], 1f, 1f);
			AeroRipple projectile = currentAR;
			float newMoveSpeed = speedArr[givenIndex];
			FireProjectile(projectile, givenVector, setKnockbackVector: true, newMoveSpeed, timeArr[givenIndex], string.Empty);
		}
		private void PlayAudio(Vector2 givenPosition, bool useBlast = true)
		{
		}
	}
