		private Vector2[] ultVecArray = new Vector2[5];
		private static int ultShotCount = 15;
		private static int ultBeamCount = 5;
		private static int ultHalfCount = 2;
		private int ultIndex;
		private ChaosQuickStopwatch ultStopwatch = new ChaosQuickStopwatch(4f);
		private float ultLerpValue;
		public UseAquaBeam(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			beamPrefab = AquaBeam.Prefab;
		}
		public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			base.SetEmpowered(givenStatus, givenMod);
			beamThickness = ((!IsEmpowered) ? 1f : 1.5f);
		}
		public override void OnEnter()
		{
			base.OnEnter();
			shotDelay = ((!isUltimate) ? 0.125f : 0.08f);
			ultLerpValue = 0f;
		}
		public override bool StartAttack()
		{
			if (attackStarted)
			{
				return true;
			}
			BaseStartAttack();
			if (attackStarted)
			{
				currentPosition = parent.attackOriginTrans.position;
				CameraController.ShakeCamera(0.25f);
				if (isUltimate)
				{
					for (int i = 0; i < ultBeamCount; i++)
					{
						ultIndex = i - ultHalfCount;
						ref Vector2 reference = ref ultVecArray[i];
						reference = Globals.GetRotatedCircleVector(10, ultIndex, targetVector);
						ultBeamArray[i] = CreateBeam(currentPosition, ultVecArray[i] * 1.25f, ultShotCount);
						ultBeamArray[i].setKnockbackOverwrite = ultIndex == 0;
					}
					ultStopwatch.IsRunning = true;
					shotStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, shotDelay, ultShotCount);
				}
				else
				{
					CreateBeam(currentPosition, targetVector, cooldownRef.chargeCount);
				}
			}
			return attackStarted;
		}
		public override void UpdateBeamVector()
		{
			if (isUltimate)
			{
				currentPosition = parent.attackOriginTrans.position;
				ultLerpValue = ultStopwatch.TimePercentage;
				for (int i = 0; i < ultBeamCount; i++)
				{
					currentBeam = ultBeamArray[i];
					if (!(currentBeam == null))
					{
						ultIndex = i - ultHalfCount;
						ref Vector2 reference = ref ultVecArray[i];
						reference = Vector2.Lerp(ultVecArray[i], targetVector, ultLerpValue);
						PointBeam(currentBeam, currentPosition + Globals.GetRotatedCircleVector(10, ultIndex, targetVector), ultVecArray[i]);
						if (ultIndex == 0)
						{
							currentBeam.attack.knockbackOverwriteVector = targetVector;
						}
						else
						{
							currentBeam.attack.knockbackOverwriteVector = Vector2.Lerp(Globals.GetPerpendicular(ultVecArray[i], ultIndex < 0), targetVector, ultLerpValue);
						}
					}
				}
				currentBeam = null;
			}
			else
			{
				base.UpdateBeamVector();
			}
		}
		public override void OnExit()
		{
			base.OnExit();
			if (currentBeam != null)
			{
				currentBeam.StopBeam();
			}
			for (int i = 0; i < ultBeamCount; i++)
			{
				if (ultBeamArray[i] != null)
				{
					ultBeamArray[i].StopBeam();
				}
			}
		}
	}
	public class UseAquaBlitz : SkillState
	{
		public new static string staticID = "UseAquaBlitz";
		private static int atkCount = 7;
		private static int halfCount = 3;
		private static float atkInterval = 0.12f;

	private static int atkCount = 7;
	private static int halfCount = 3;
	private static float atkInterval = 0.12f;
	private int atkStopwatchID;
	private bool atkCompleted;
	private bool comboCompleted;
	private List<AquaBlitzBall> abList = new List<AquaBlitzBall>();
	private AquaBlitzBall currentAB;
	private Vector2 spawnPosition;
	private Vector2 offsetVec;
	private Vector3 aimVector;
	private static float atkMoveSpeed = 8f;
	private WaterBlast shieldWB;
	private int shieldOriginalValue;
	private bool shieldValueReset;
	private bool useEmpowered;
	private bool empStarted;
	public override string OnEnterAnimStr => parent.PBAoEAnimStr;
	public UseAquaBlitz(FSM parentFSM, Player parentEnt)
		: base(staticID, parentFSM, parentEnt)
	{
		isMovementSkill = true;
		isMeleeSkill = true;
		SetAnimTimes(0.25f, 0.2f, 0.25f, 0.45f, 0.65f);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		offsetVec = -inputVector * 0.2f;
		parent.movement.moveVector = inputVector;
		atkCompleted = false;
		comboCompleted = false;
		abList.Clear();
		atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, atkInterval, atkCount);
		for (int i = 0; i < atkCount; i++)
		{
			CreateAquaBlitz(i);
		}
		abList.Shuffle();
		useEmpowered = IsEmpowered;
		if (useEmpowered)
		{
			empStarted = false;
			shieldValueReset = false;
			CreateShield();
			shieldOriginalValue = parent.health.CurrentShieldValue;
			parent.health.CurrentShieldValue += 50;
			ApplyStopElement();
			parent.movement.MoveToMoveVector(atkMoveSpeed * 2f);
		}
	}
	public override void ExecuteSkill()
	{
		CancelToDash(enableButtonHeld: true);
		if (!atkCompleted)
		{
			if (!comboCompleted)
			{
				switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
				{
				case StopwatchState.Ready:
					PlayAnimAndMove();
					FireAquaBlitz();
					break;
				case StopwatchState.Done:
					comboCompleted = true;
					atkStopwatchID = ChaosStopwatch.Begin(atkInterval);
					break;
				}
			}
			if (ChaosStopwatch.Check(atkStopwatchID))
			{
				atkCompleted = true;
				PlayAnimAndMove();
				if (useEmpowered)
				{
					atkStopwatchID = ChaosStopwatch.Begin(atkInterval);
				}
			}
			return;
		}
		if (useEmpowered)
		{
			if (!ChaosStopwatch.Check(atkStopwatchID))
			{
				return;
			}
			if (!empStarted)
			{
				empStarted = true;
				parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, 0.2f);
				parent.movement.MoveToMoveVector(24f);
				return;
			}
			parent.movement.EndMovement();
			ResetShieldValue();
			if (shieldWB != null)
			{
				shieldWB.Blast();
			}
		}
		base.ExecuteSkill();
	}
	public override void OnExit()
	{
		if (!fsm.nextStateName.Contains("Hurt") && !fsm.nextStateName.Contains("Dead"))
		{
			ResetShieldValue();
		}
		base.OnExit();
		for (int num = abList.Count - 1; num >= 0; num--)
		{
			if (!abList[num].activated)
			{
				abList[num].Reset();
			}
		}
		if (shieldWB != null)
		{
			shieldWB.Dissipate();
		}
	}
	private void CreateShield()
	{
		shieldWB = ChaosInst<WaterBlast>(WaterBlast.Prefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(inputVector));
		shieldWB.attack.SetAttackInfo(parent.skillCategory, skillID, 2);
		shieldWB.attack.knockbackOverwriteVector = inputVector;
		shieldWB.attack.transform.localScale *= 1.5f;
		shieldWB.blastSkillLevel = 3;
		shieldWB.gameObject.AddComponent<FollowTransform>().followTransform = parent.attackOriginTrans;
	}
	private void ResetShieldValue()
	{
		if (IsEmpowered && !shieldValueReset)
		{
			shieldValueReset = true;
			if (parent.health.CurrentShieldValue > shieldOriginalValue)
			{
				parent.health.CurrentShieldValue = shieldOriginalValue;
			}
		}
	}
	private void CreateAquaBlitz(int givenIndex)
	{
		offsetVec = Globals.GetRotatedCircleVector(30, givenIndex - halfCount, -inputVector);
		spawnPosition = (Vector2)parent.attackOriginTrans.position + offsetVec;
		currentAB = ChaosInst<AquaBlitzBall>(AquaBlitzBall.Prefab, spawnPosition);
		currentAB.attack.SetAttackInfo(parent.skillCategory, skillID);
		currentAB.idlePosition = spawnPosition + offsetVec * UnityEngine.Random.Range(1.25f, 1.75f);
		currentAB.idleVector = offsetVec;
		abList.Add(currentAB);
	}
	private void FireAquaBlitz()
	{
		if (abList.Count > 0 && !(abList[0] == null))
		{
			currentAB = abList[0];
			abList.RemoveAt(0);
			aimVector = (inputVector + UnityEngine.Random.insideUnitCircle * 0.2f).normalized;
			currentAB.Activate(parent.attackOriginTrans.position + aimVector, aimVector, (parent.attackOriginTrans.position - currentAB.transform.position).normalized);
		}
	}
	private void PlayAnimAndMove()
	{
		parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animExecTime);
		parent.movement.MoveToMoveVector(atkMoveSpeed);
	}
}
