public class UseBlazingBlitz : SkillState
{
	public new static string staticID = "UseBlazingBlitz";
	private bool finishedDashing;
	private NumVarStatMod baseDashMod;
	private NumVarStatMod ultDashMod;
	private int particleCounter;
	private FireBurst fireBurst;
	private Entity targetEntity;
	private Vector2 targetOffset;
	private GameObject currentAtkObj;
	private Attack currentAtk;
	private int comboStopwatchID;
	private float hitDelay = 0.1f;
	private int hitCount = 6;
	private float comboFinishDelay = 0.125f;
	private float exitDelay = 0.25f;
	private bool targetHit;
	private bool targetIsAlive;
	private bool comboFinished;
	private bool finalAttackFinished;
	private bool targetGrabbed;
	private bool targetCanBeMoved;
	private BoolVarStatMod ultImmunityMod;
	private Vector2 initInputVec;
	private Vector2 currentPosition;
	private Vector3 currentRotation;
	public UseBlazingBlitz(FSM parentFSM, Player parentEnt)
		: base(staticID, parentFSM, parentEnt)
	{
		hasSignatureVariant = true;
		isMeleeSkill = true;
		isMovementSkill = true;
		SetAnimTimes(0.15f, 0.2f, 0.3f, 0.5f);
		baseDashMod = new NumVarStatMod(staticID, 0.15f, 10, VarStatModType.OverrideWithMods);
		ultDashMod = new NumVarStatMod(staticID, 0.2f, 10, VarStatModType.OverrideWithMods);
		ultImmunityMod = new BoolVarStatMod(staticID, newModValue: true);
	}
	public override void OnEnter()
	{
		BaseOnEnter();
		base.ExecuteSkill();
		finishedDashing = false;
		if (isUltimate)
		{
			parent.movement.dashDurationStat.AddMod(ultDashMod);
			parent.movement.dashTimer = ultDashMod.modValue;
		}
		else
		{
			parent.movement.dashDurationStat.AddMod(baseDashMod);
			parent.movement.dashTimer = baseDashMod.modValue;
		}
		inputVector = GetInputVector();
		initInputVec = inputVector;
		parent.movement.dashVector = inputVector;
		parent.anim.PlayDirectional(parent.DashAnimStr);
		parent.TogglePreventFallCollider(status: false);
		parent.ToggleEnemyFloorCollisions(status: false);
		currentRotation = Globals.GetRotationVector(-inputVector);
		currentAtkObj = UnityEngine.Object.Instantiate(Attack.CirclePrefab, parent.attackOriginTrans.position, Quaternion.identity, parent.attackOriginTrans);
		currentAtk = currentAtkObj.GetComponent<Attack>();
		currentAtk.SetAttackInfo(parent.skillCategory, skillID, (!isUltimate) ? 1 : 5, isUltimate);
		Attack attack = currentAtk;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(SetHitTarget));
		Attack attack2 = currentAtk;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(SetHitTarget));
		currentAtk.knockbackOverwriteVector = inputVector;
		targetHit = false;
		targetIsAlive = false;
		targetEntity = null;
		targetGrabbed = false;
		targetCanBeMoved = false;
		comboFinished = false;
		finalAttackFinished = false;
		fireBurst = Globals.ChaosInst<FireBurst>(FireBurst.Prefab, null, parent.transform.position);
		fireBurst.SetSortLayer("Effect");
	}
	public override void Update()
	{
		if (!finishedDashing)
		{
			return;
		}
		if (!targetHit)
		{
			fsm.ChangeState(SlideState.staticID);
			return;
		}
		if (targetIsAlive && (targetEntity == null || targetEntity.currentStateName == "Dead" || targetEntity.hurtBoxTransform == null || targetEntity.rigidbody2D == null))
		{
			targetIsAlive = false;
			comboFinished = true;
			finalAttackFinished = true;
			comboStopwatchID = ChaosStopwatch.Begin(exitDelay);
		}
		if (!comboFinished)
		{
			CancelToDash();
		}
		else if (!finalAttackFinished)
		{
			parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, animStartTime);
			if (ChaosStopwatch.Check(comboStopwatchID))
			{
				finalAttackFinished = true;
				SetTargetEntityImmunity(givenStatus: false);
				currentAtkObj.transform.position = parent.attackOriginTrans.position;
				currentAtk.ChangeAttackInfoLevel((!isUltimate) ? 2 : 4);
				currentPosition = (Vector2)parent.transform.position + initInputVec * 0.75f;
				if (isUltimate)
				{
					CreateUltBurst(currentAtk.transform.position, currentAtk.atkInfo, 1.75f);
					CreateFlamePillar(currentPosition, 3f);
					int? particleCount = 10;
					Vector3? position = currentPosition;
					Vector3? localEulerAngles = Globals.Vector3Angle45CW;
				}
				else
				{
					(currentAtk.collider as CircleCollider2D).radius = 2.5f;
					currentAtkObj.SetActive(value: true);
					FireExplosion.SpawnExplosion(parent.attackOriginTrans.position, 1.25f, 1f, 50, 50);
					int? particleCount = 16;
					Vector3? localEulerAngles = currentPosition;
					Vector3? position = Globals.GetRotationVector((initInputVec * 0.75f + Vector2.up).normalized);
				}
				comboStopwatchID = ChaosStopwatch.Begin(exitDelay);
			}
		}
		else
		{
			CleanUpObjects();
			if (ChaosStopwatch.Check(comboStopwatchID))
			{
				ExitToSkillOrRunOrIdle();
			}
		}
	}
	public override void FixedUpdate()
	{
		if (!finishedDashing)
		{
			currentAtk.rigidbody2D.MovePosition(parent.attackOriginTrans.position);
			if (!parent.movement.DashToTarget())
			{
				return;
			}
			finishedDashing = true;
		}
		if (comboFinished)
		{
			return;
		}
		if (targetEntity == null)
		{
			currentAtkObj.SetActive(value: false);
			comboFinished = true;
			comboStopwatchID = ChaosStopwatch.Begin(comboFinishDelay);
			return;
		}
		switch (ChaosStopwatch.CheckInterval(comboStopwatchID))
		{
		case StopwatchState.Running:
			currentAtkObj.SetActive(value: false);
			break;
		case StopwatchState.Ready:
		{
			parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animExecTime);
			currentPosition = parent.transform.position;
			MoveTargetEntity(currentPosition + inputVector + targetOffset);
			if (isUltimate)
			{
				CreateUltBurst(currentAtk.transform.position, currentAtk.atkInfo, 1.5f);
				hitDelay *= 0.8f;
				ChaosStopwatch.SetIntervalTime(comboStopwatchID, hitDelay);
				break;
			}
			if (targetEntity.health.CurrentHealthValue < 25)
			{
				ChaosStopwatch.Stop(comboStopwatchID);
				break;
			}
			currentAtkObj.SetActive(value: true);
			FireBurst fireBurst = this.fireBurst;
			int? particleCount = 5;
			Vector3? position = parent.attackOriginTrans.position;
			Vector3? localEulerAngles = Globals.GetRotationVector(inputVector);
			fireBurst.EmitSingle(particleCount, position, null, localEulerAngles);
			break;
		}
		case StopwatchState.Done:
			currentAtkObj.SetActive(value: false);
			CameraController.ShakeCamera();
			parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, animStartTime);
			MoveTargetEntity(parent.transform.position + (Vector3)inputVector * 0.5f);
			comboFinished = true;
			comboStopwatchID = ChaosStopwatch.Begin(comboFinishDelay);
			break;
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		parent.TogglePreventFallCollider(status: true);
		parent.ToggleEnemyFloorCollisions();
		SetTargetEntityImmunity(givenStatus: false);
		parent.movement.dashDurationStat.RemoveMod(staticID);
		CleanUpObjects();
	}
	private void CleanUpObjects()
	{
		if (currentAtk != null)
		{
			Attack attack = currentAtk;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(SetHitTarget));
		}
		if (currentAtkObj != null)
		{
			UnityEngine.Object.Destroy(currentAtkObj, 0.05f);
		}
		if (fireBurst != null && fireBurst.gameObject != null)
		{
			UnityEngine.Object.Destroy(fireBurst.gameObject, 2f);
		}
	}
	{
		particleCounter = Mathf.Max(2, particleCounter - 1);
		FireBurst fireBurst = this.fireBurst;
		int? particleCount = particleCounter;
		Vector3? position = parent.attackOriginTrans.position + (Vector3)inputVector;
		Vector3? localEulerAngles = currentRotation;
		fireBurst.EmitSingle(particleCount, position, null, localEulerAngles);
	}
	private void SetHitTarget(Entity ent)
	{
		if (!targetHit && !(ent == null) && !(ent is Destructible))
		{
			targetHit = true;
			targetIsAlive = true;
			finishedDashing = true;
			parent.TogglePreventFallCollider(status: true);
			parent.movement.EndMovement();
			targetEntity = ent;
			targetGrabbed = targetEntity.health != null && !targetEntity.health.ignoreGrab;
			targetOffset = new Vector2(0f, targetEntity.hurtBoxTransform.position.y - targetEntity.transform.position.y - 0.9f);
			(currentAtk.collider as CircleCollider2D).radius = 0.75f;
			Attack attack = currentAtk;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(SetHitTarget));
			currentAtkObj.SetActive(value: false);
			parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animExecTime);
			SetComboValues();
			comboStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, hitCount - 1);
			MoveTargetEntity((Vector2)parent.transform.position + inputVector + targetOffset);
			if (isUltimate)
			{
				SetTargetEntityImmunity(givenStatus: true);
				currentAtk.ChangeAttackInfoLevel(3);
				CreateUltBurst(currentAtk.transform.position, currentAtk.atkInfo, 1.5f);
			}
		}
	}
	private void MoveTargetEntity(Vector2 givenPosition)
	{
		if (targetEntity != null && (targetCanBeMoved || (targetGrabbed && !targetEntity.health.IgnoreKnockback)))
		{
			targetCanBeMoved = true;
			targetEntity.rigidbody2D.MovePosition(givenPosition);
			currentAtkObj.transform.position = targetEntity.hurtBoxTransform.position;
		}
		else
		{
			currentAtkObj.transform.position = parent.attackOriginTrans.position + (Vector3)inputVector;
		}
	}
	private void SetTargetEntityImmunity(bool givenStatus)
	{
		if (targetEntity != null && targetEntity.health != null)
		{
			targetEntity.health.ignoreKnockbackVarStat.Modify(ultImmunityMod, givenStatus);
			targetEntity.health.deathProof.Modify(ultImmunityMod, givenStatus);
		}
	}
	private void SetComboValues()
	{
		if (isUltimate)
		{
			hitCount = 5;
			hitDelay = 0.12f;
			comboFinishDelay = 0.15f;
			exitDelay = 0.2f;
		}
		else if (IsEmpowered)
		{
			hitCount = 10;
			hitDelay = 0.08f;
			comboFinishDelay = 0.1f;
			exitDelay = 0.125f;
		}
		else
		{
			hitCount = 6;
			hitDelay = 0.1f;
			comboFinishDelay = 0.12f;
			exitDelay = 0.15f;
		}
	}
	private void CreateUltBurst(Vector2 givenPosition, AttackInfo givenInfo, float givenScale)
	{
		FlameBurst.CreateBurst(givenPosition, givenInfo, givenScale).attack.knockbackOverwriteVector = inputVector;
		FireExplosion.SpawnExplosion(givenPosition, givenScale, 1f, 50, 25);
	}
	private void CreateFlamePillar(Vector2 givenPosition, float givenScale)
	{
		FirePillar firePillar = ChaosInst<FirePillar>(FirePillar.Prefab, givenPosition);
		Attack attack = firePillar.attack;
		string skillCategory = parent.skillCategory;
		string newSkillID = "StandardFirePillar";
		bool newIsUltimate = isUltimate;
		attack.SetAttackInfo(skillCategory, newSkillID, 1, newIsUltimate);
		firePillar.delay = 1f / 32f;
		firePillar.duration = 1.75f;
		firePillar.castingCircleColor = CastingCircle.defaultColor;
		firePillar.attackRadius = givenScale;
	}
}
public class UseBlazingCombo : ProjectileAttackState
{
	public new static string staticID = "UseBlazingCombo";
	private BlazingComboProjectile currentBC;
	private ChaosQuickStopwatch delayStopwatch = new ChaosQuickStopwatch(0.08f);
	private bool delayStarted;
	private bool delayCompleted;
	private bool targetHit;
	private bool targetStop;
	private int comboCountMax = 4;
	private int comboCounter;
	public override string OnEnterAnimStr => parent.ForehandAnimStr;
	private Vector2 HoldPosition => (Vector2)parent.attackOriginTrans.position - inputVector * 0.25f;
	public UseBlazingCombo(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isMovementSkill = true;
		SetAnimTimes(0.1f, 0.2f, 0.25f, 0.7f, 0.9f);
	}
	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		comboCountMax = ((!IsEmpowered) ? 4 : 5);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		delayStarted = false;
		delayCompleted = false;
		targetHit = false;
		targetStop = false;
		comboCounter = 0;
	}
	public override void ExecuteSkill()
	{
		if (!delayStarted)
		{
			delayStarted = true;
			delayStopwatch.SetDelay(0.08f, stopCurrent: false, autoStart: true);
			parent.ToggleEnemyFloorCollisions(status: false);
			parent.movement.moveVector = inputVector;
			parent.movement.MoveToMoveVector(60f);
			CreateCombo(isPrimary: true);
		}
		if (!delayCompleted && delayStopwatch.IsRunning)
		{
			if (comboCounter == 0)
			{
				parent.anim.PlayDirectional(OnEnterAnimStr, -1, animExecTime);
			}
			else
			{
				CancelToDash();
			}
			return;
		}
		if (comboCounter < comboCountMax)
		{
			if (comboCounter == 0)
			{
				ThrowCombo(isFinal: false);
				parent.movement.EndMovement();
				parent.movement.MoveToMoveVector(10f);
			}
			comboCounter++;
			if (comboCounter == 1)
			{
				parent.anim.PlayDirectional(parent.LastHandAnimStr, -1, 0.3f);
				delayStopwatch.SetDelay((!IsEmpowered) ? 0.15f : 0.1f);
			}
			else
			{
				parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, 0.3f);
				CreateCombo();
				ThrowCombo(comboCounter == comboCountMax);
			}
			if (comboCounter <= comboCountMax)
			{
				delayStopwatch.IsRunning = true;
				return;
			}
		}
		delayCompleted = true;
		parent.anim.PlayDirectional(parent.LastHandAnimStr, -1, 0.3f);
		base.ExecuteSkill();
	}
	public override void FixedUpdate()
	{
		if (!delayCompleted && currentBC != null)
		{
			currentBC.transform.position = HoldPosition;
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		parent.movement.EndMovement();
		parent.ToggleEnemyFloorCollisions();
		if (currentBC != null)
		{
			currentBC.ResetProjectile();
		}
	}
	private void CreateCombo(bool isPrimary = false)
	{
		currentBC = (BlazingComboProjectile)CreateProjectile(BlazingComboProjectile.Prefab, HoldPosition, Globals.GetRotationQuaternion(inputVector));
		currentBC.targetVector = inputVector;
		currentBC.attackBox.knockbackOverwriteVector = inputVector;
		if (isPrimary)
		{
			currentBC.grabTargets = true;
			currentBC.attackBox.SetAttackInfo(parent.skillCategory, skillID, 2);
			Attack attackBox = currentBC.attackBox;
			attackBox.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attackBox.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attackBox2 = currentBC.attackBox;
			attackBox2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attackBox2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
		else
		{
			currentBC.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			currentBC.firePartSys.Stop();
		}
	}
	private void ThrowCombo(bool isFinal)
	{
		if (!(currentBC == null))
		{
			currentBC.attackBox.ChangeAttackInfoLevel(1);
			currentBC.SetBurstInfo(parent.skillCategory, skillID, (!isFinal) ? 2 : 3);
			currentBC.transform.position = parent.attackOriginTrans.position;
			currentBC.goThroughWalls = false;
			currentBC.disableOnHit = true;
			Attack attackBox = currentBC.attackBox;
			attackBox.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attackBox.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			currentBC.isFinal = isFinal;
			currentBC.grabTargets = false;
			FireProjectile(currentBC, inputVector, setKnockbackVector: true, 36f, (!targetStop) ? (0.08f + (float)comboCounter * 0.01f) : 0.01f, string.Empty);
			currentBC = null;
			if (isFinal)
			{
				CameraController.ShakeCamera(0.25f);
			}
		}
	}
	private void OnTargetHit(Entity givenEntity)
	{
		if (!(givenEntity == null) && !(givenEntity is Destructible))
		{
			targetHit = true;
			if (givenEntity.health.ignoreGrab)
			{
				parent.movement.EndMovement();
				targetStop = true;
			}
		}
	}
}
