public class UseChaosMirror : SkillState
{
	public new static string staticID = "UseChaosMirror";
	private SkillState lastSkillState;
	private bool requiresUnempower;
	private BoolVarStatMod empowerMod;
	private NumVarStatMod statusMod;
	private NumVarStatMod stunMod;
	public UseChaosMirror(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		SetAnimTimes(0.15f, 0.2f, 0.3f, 0.7f);
		empowerMod = new BoolVarStatMod("ChaosMirrorEmpowerMod", newModValue: true);
		Player player = parent;
		player.skillEnterEventHandlers = (SkillEventHandler)Delegate.Combine(player.skillEnterEventHandlers, new SkillEventHandler(RecordLastSkill));
		Player player2 = parent;
		player2.skillExitEventHandlers = (SkillEventHandler)Delegate.Combine(player2.skillExitEventHandlers, new SkillEventHandler(UnempowerLastSkill));
		statusMod = new NumVarStatMod("ChaosMirrorStatusMod", 1f, 10, VarStatModType.Override);
		stunMod = new NumVarStatMod("ChaosMirrorStunMod", 3f, 10, VarStatModType.Override);
	}
	private void RecordLastSkill(SkillState givenSkill)
	{
		if (givenSkill.skillID != staticID && !givenSkill.isBasic && !givenSkill.isDash)
		{
			lastSkillState = givenSkill;
		}
	}
	private void UnempowerLastSkill(SkillState givenSkill)
	{
		if (requiresUnempower && !(givenSkill.skillID == staticID) && !(lastSkillState.skillID != givenSkill.skillID))
		{
			lastSkillState.SetEmpowered(givenStatus: false, empowerMod);
			SetMod(enableMod: false);
			requiresUnempower = false;
		}
	}
	public void SetMod(bool enableMod = true)
	{
		NumVarStatMod numVarStatMod = statusMod;
		string text = string.Empty;
		switch (lastSkillState.element)
		{
		case ElementType.Fire:
			text = "burnChance";
			break;
		case ElementType.Lightning:
			text = "shockChance";
			break;
		case ElementType.Air:
			text = "slowChance";
			break;
		case ElementType.Earth:
			numVarStatMod = stunMod;
			text = "hitStunDurationModifier";
			break;
		case ElementType.Water:
			text = "freezeChance";
			break;
		case ElementType.Ice:
			text = "freezeChance";
			break;
		case ElementType.Poison:
			text = "poisonChance";
			break;
		}
		if (!(text == string.Empty))
		{
			if (enableMod)
			{
				lastSkillState.skillData.AddMod(text, numVarStatMod);
			}
			else
			{
				lastSkillState.skillData.RemoveMod(text, numVarStatMod.ID);
			}
		}
	}
	public override void OnEnter()
	{
		base.OnEnter();
		if (lastSkillState != null)
		{
			lastSkillState.SetEmpowered(givenStatus: true, empowerMod);
			SetMod();
			if (lastSkillState.isChargeSkill)
			{
				lastSkillState.cooldownRef.Reset();
			}
			requiresUnempower = true;
			parent.fsm.ChangeState(lastSkillState.skillID);
		}
	}
}
