		baseCancelThreshold = 0.55f;
		finalCancelThreshold = 0.75f;
		baseRunThreshold = 0.8f;
		finalRunThreshold = 0.9f;
		attackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 8f, 10, VarStatModType.OverrideWithMods);
		finalAttackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 16f, 10, VarStatModType.OverrideWithMods);
		chargeAtkMoveSpeed = 24f;
		autoHoldStat.BaseValue = true;
	}
	public override void SetEmpowered(bool gs, BoolVarStatMod ms)
	{
	}
	public override void OnEnter()
	{
		base.OnEnter();
		atkStarted = false;
		atkCompleted = false;
		queueFinalSpin = false;
	}
	public override void ExecuteAttack()
	{
		if (!atkStarted)
		{
			base.ExecuteAttack();
			if (useBaseMAS)
			{
				CameraController.ShakeCamera(0.12f);
				return;
			}
			if (!isCharged)
			{
				currentAttackObject.attack.ChangeAttackInfoLevel(2);
				PlayAttackObjAnim("SwingLarge");
				CameraController.ShakeCamera(0.18f);
				return;
			}
			spinAnimStr = ((!parent.forehandAnimPlayed) ? "Spin" : "SpinReverse");
			currentAttackObject.attack.ChangeAttackInfoLevel(3);
			currentAttackObject.negateScript.enabled = true;
			currentAttackObject.negateScript.skillCategory = parent.skillCategory;
			currentAttackObject.useAnimTime = false;
			atkStarted = true;
			atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.15f, 2);
		}
		attackExecuted = atkCompleted;
	}
	public override void FixedUpdate()
	{
		if (!atkStarted || atkCompleted)
		{
			return;
		}
		if (!queueFinalSpin)
		{
			switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
			{
			case StopwatchState.Ready:
				parent.movement.MoveToMoveVector();
				parent.anim.Play(spinAnimStr, -1, 0f);
				PlayAttackObjAnim("SpinFront");
				break;
			case StopwatchState.Done:
				queueFinalSpin = true;
				atkStopwatchID = ChaosStopwatch.Begin(0.15f);
				break;
			}
			return;
		}
		CancelToDash(enableButtonHeld: true);
		if (ChaosStopwatch.Check(atkStopwatchID))
		{
			atkCompleted = true;
			parent.movement.MoveToMoveVector();
			parent.anim.PlayDirectional(parent.LastHandAnimStr, -1, animExecTime);
			PlayAttackObjAnim("SwingLarge");
			if (currentAttackObject != null)
			{
				currentAttackObject.useLifeTime = true;
				currentAttackObject.lifeStopwatchID = ChaosStopwatch.Begin(0.5f);
				currentAttackObject.attack.ChangeAttackInfoLevel(4);
				(currentAttackObject as ChaosScytheObject).EmitRing();
			}
			if (repeatFinalHit)
			{
				cancelThreshold = baseCancelThreshold;
			}
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		if (!attackExecuted && currentAttackObject != null)
		{
			currentAttackObject.useAnimTime = true;
		}
	}
	private void PlayAttackObjAnim(string givenStr)
	{
		if (currentAttackObject != null)
		{
			currentAttackObject.anim.Play(givenStr, -1, 0f);
		}
	}
}
public class UseChaosStasis : SkillState
{
	public new static string staticID = "UseChaosStasis";
	private List<Enemy> enemies = new List<Enemy>();
	private Dictionary<Entity, List<AttackInfo>> atkHistory = new Dictionary<Entity, List<AttackInfo>>();
	private ChaosQuickStopwatch stasisTimer;
	private float stasisDuration = 2.5f;
	private float stasisRadius = 6f;
	private AttackInfo stasisAttack;
	private int maxAtkCounter;
	public override string OnEnterAnimStr => parent.GSlamAnimStr;
	public UseChaosStasis(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		SetAnimTimes(0.2f, 0.2f, 0.3f, 0.75f, 0.9f);
		stasisTimer = new ChaosQuickStopwatch(stasisDuration);
		stasisAttack = new AttackInfo();
		stasisAttack.skillID = "ChaosStasis" + parentPlayer.playerID;
		stasisAttack.damage = 0;
		stasisAttack.elementType = ElementType.Neutral;
		stasisAttack.showDamageNumber = false;
		stasisAttack.isCritical = false;
		stasisAttack.knockbackVector = Vector3.zero;
		stasisAttack.knockbackMultiplier = 0f;
		stasisAttack.knockbackOverwrite = false;
	}
	public override void OnEnter()
	{
		base.OnEnter();

		base.OnEnter();
		enemies.Clear();
		atkHistory.Clear();
		maxAtkCounter = 0;
	}
	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		parent.StartCoroutine(HandleStatis());
	}
	private void OnEntityCollision(Entity entity)
	{
		if (entity is Enemy)
		{
			enemies.Add((Enemy)entity);
		}
	}
	private void HijackAttackInfo(AttackInfo atkInfo, Entity atkEntity, Entity hurtEntity)
	{
		if (!atkHistory.ContainsKey(hurtEntity))
		{
			atkHistory[hurtEntity] = new List<AttackInfo>();
		}
		atkHistory[hurtEntity].Add(new AttackInfo(atkInfo));
		if (maxAtkCounter == 0 || atkHistory[hurtEntity].Count > maxAtkCounter)
		{
			maxAtkCounter = atkHistory[hurtEntity].Count;
		}
		atkInfo.skillID = stasisAttack.skillID;
		atkInfo.damage = stasisAttack.damage;
		atkInfo.elementType = ElementType.Neutral;
		atkInfo.showDamageNumber = false;
		atkInfo.isCritical = false;
		atkInfo.knockbackVector = Vector3.zero;
		atkInfo.knockbackMultiplier = 0f;
		atkInfo.knockbackOverwrite = false;
	}
	private IEnumerator HandleStatis()
	{
		Attack newAttack = Globals.ChaosInst<Attack>(Attack.CirclePrefab, null, parent.transform.position);
		newAttack.SetAttackInfo(parent.skillCategory, staticID);
		((CircleCollider2D)newAttack.collider).radius = stasisRadius;
		newAttack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(newAttack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnEntityCollision));
		yield return null;
		UnityEngine.Object.Destroy(newAttack.gameObject);
		enemies.RemoveAll((Enemy e) => e == null);
		if (enemies.Count == 0)
		{
			yield break;
		}
		for (int num = 0; num < enemies.Count; num++)
		{
			if (!(enemies[num] == null))
			{
				enemies[num].enabled = false;
				enemies[num].spriteRenderer.color = new Color(0.7f, 0.6f, 1f, 0.5f);
				Health health = enemies[num].health;
				health.takeDamageEnterHandlersWithHurtEntity = (Health.OnTakeDamageHandlerWithHurtEntity)Delegate.Combine(health.takeDamageEnterHandlersWithHurtEntity, new Health.OnTakeDamageHandlerWithHurtEntity(HijackAttackInfo));
			}
		}
		stasisTimer.IsRunning = true;
		while (stasisTimer.IsRunning)
		{
			yield return null;
		}
		for (int num2 = 0; num2 < enemies.Count; num2++)
		{
			if (!(enemies[num2] == null))
			{
				enemies[num2].enabled = true;
				enemies[num2].spriteRenderer.color = Color.white;
				Health health2 = enemies[num2].health;
				health2.takeDamageEnterHandlersWithHurtEntity = (Health.OnTakeDamageHandlerWithHurtEntity)Delegate.Remove(health2.takeDamageEnterHandlersWithHurtEntity, new Health.OnTakeDamageHandlerWithHurtEntity(HijackAttackInfo));
			}
		}
		int atkCounter = 0;
		for (int i = 0; i < maxAtkCounter; i++)
		{
			foreach (KeyValuePair<Entity, List<AttackInfo>> atkEntry in atkHistory)
			{
				List<AttackInfo> atkList = atkEntry.Value;
				if (atkList != null && atkList.Count > atkCounter)
				{
					atkEntry.Key.health.TakeDamage(atkList[atkCounter]);
					atkCounter++;
					yield return new WaitForSeconds(0.05f);
				}
			}
		}
	}
}
public class UseChaosSwordStorm : SkillState
{
	public new static string staticID = "UseChaosSwordStorm";
	private static string[] emitterNames = new string[3] { "ChaosSwordStraight", "ChaosSwordRight", "ChaosSwordLeft" };
	private static int waveMaxCount = 7;
	private int waveSideCount;
	private int randSwordCount;
	private Vector2 waveVec;
	private Vector2 startPos;
	private Vector2 perpVec;
	private float waveDelay = 0.03f;
	private int waveStopwatchID;
	private int waveCounter;
	private bool waveCompleted;
	private float randDelay = 0.04f;
	private int randStopwatchID;
	private bool randCompleted;
	private float initDelay = 0.25f;
	private float dropDelay = 0.3f;
	private ChaosQuickStopwatch audioStopwatch;
	private bool swordsCompleted;
	private List<int> timeIDList = new List<int>();
	private Dictionary<int, Vector2> timePosDict = new Dictionary<int, Vector2>();
	public override string OnEnterAnimStr => parent.GSlamAnimStr;
	public UseChaosSwordStorm(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		hasSignatureVariant = true;
		empoweredStat.SetInitialBaseValue(newBaseVal: true);
		SetAnimTimes(0f, 0.2f, 0f, 0.55f, 0.75f);
	}
	public override void SetEmpowered(bool gs, BoolVarStatMod gm)
	{
	}
	public override void OnEnter()
	{
		base.OnEnter();
		if (isUltimate)
		{
			initDelay = 0f;
			randDelay = 0.02f;
			randSwordCount = 100;
			waveDelay = 0f;
			waveSideCount = 3;
		}
		else
		{
			initDelay = 0.25f;
			randDelay = 0.04f;
			randSwordCount = 35;
			waveDelay = 0.03f;
			waveSideCount = 2;
		}
	}
	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		waveVec = inputVector * 1.125f;
		startPos = (Vector2)parent.transform.position + waveVec;
		perpVec = Globals.GetPerpendicular(inputVector);
		parent.StartCoroutine(SpawnSwords(isUltimate));
	}
	private IEnumerator SpawnSwords(bool isUlt)
	{
		waveStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, waveDelay, waveMaxCount);
		waveCounter = 0;
		waveCompleted = false;
		randStopwatchID = ChaosStopwatch.Begin(initDelay, useInterval: true, randDelay, randSwordCount);
		randCompleted = false;
		if (audioStopwatch == null)
		{
			audioStopwatch = new ChaosQuickStopwatch(0.1f);
		}
		timeIDList.Clear();
		timePosDict.Clear();
		swordsCompleted = false;
		while (!swordsCompleted)
		{
			if (!waveCompleted)
			{
				switch (ChaosStopwatch.CheckInterval(waveStopwatchID))
				{
				case StopwatchState.Ready:
				{
					for (int i = -waveSideCount; i <= waveSideCount; i++)
					{
						QueueSword(ChaosStopwatch.Begin(dropDelay), waveVec * waveCounter + perpVec * i);
					}
					waveCounter++;
					break;
				}
				case StopwatchState.Done:
					waveCompleted = true;
					break;
				}
			}
			if (!randCompleted)
			{
				switch (ChaosStopwatch.CheckInterval(randStopwatchID))
				{
				case StopwatchState.Ready:
					QueueSword(ChaosStopwatch.Begin(dropDelay), waveVec * UnityEngine.Random.Range(0, waveMaxCount) + perpVec * UnityEngine.Random.Range(-waveSideCount, waveSideCount));
					break;
				case StopwatchState.Done:
					randCompleted = true;
					break;
				}
			}
			if (!audioStopwatch.IsRunning)
			{
				audioStopwatch.IsRunning = true;
			}
			for (int num = timeIDList.Count - 1; num >= 0; num--)
			{
				if (ChaosStopwatch.Check(timeIDList[num]))
				{
					PoolManager.GetPoolItem<AttackGeneric>().CircleAttack(timePosDict[timeIDList[num]], parent.skillCategory, skillID, currentLevel, isUlt, 1.25f);
					timeIDList.RemoveAt(num);
				}
			}
			swordsCompleted = randCompleted && waveCompleted && timeIDList.Count <= 0;
			yield return null;
		}
	}
	private void QueueSword(int givenID, Vector2 givenPosition)
	{
		givenPosition += startPos;
		timeIDList.Add(givenID);
		timePosDict.Add(givenID, givenPosition);
	}
}
public class UseChaosSwordSummon : ProjectileAttackState
{
	public new static string staticID = "UseChaosSwordSummon";
	private static WaitForSeconds waitForFlyTime = new WaitForSeconds(0.375f);
	private ChaosSwordProjectile[] swordArr = new ChaosSwordProjectile[7];
	private ChaosSwordProjectile currentCS;
	private Vector2 spawnPosition;
	private int spawnCount;
	public override string OnEnterAnimStr => parent.ForehandAnimStr;
	public UseChaosSwordSummon(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		empoweredStat.SetInitialBaseValue(newBaseVal: true);
		SetAnimTimes(0.15f, 0.2f, 0.3f, 0.55f, 0.75f);
	}
	public override void SetEmpowered(bool gs, BoolVarStatMod gm)
	{
	}
	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		spawnPosition = parent.attackOriginTrans.position;
		spawnCount = ((!isUltimate) ? 1 : 3);
		ChaosBurst.Spawn(spawnPosition, spawnCount + 1);
		CameraController.ShakeCamera(0.2f);
		for (int i = -spawnCount; i <= spawnCount; i++)
		{
			swordArr[i + spawnCount] = CreateChaosSword(spawnPosition, Globals.GetRotatedCircleVector(32, i, inputVector));
		}
		parent.StartCoroutine(HandleDetonation());
	}
	private ChaosSwordProjectile CreateChaosSword(Vector2 givenPosition, Vector2 givenVector)
	{
		currentCS = (ChaosSwordProjectile)CreateProjectile(ChaosSwordProjectile.Prefab, givenPosition + givenVector, Globals.GetRotationQuaternion(givenVector));
		currentCS.isUltimate = isUltimate;
		AttackInfo.SetHurtTargets(currentCS.attackBox.atkInfo.targetNames);
		FireProjectile(currentCS, givenVector, setKnockbackVector: true, 0f, 0f, string.Empty);
		return currentCS;
	}
	private IEnumerator HandleDetonation()
	{
		yield return waitForFlyTime;
		bool allowDetonate = false;
		for (int i = 0; i < swordArr.Length; i++)
		{
			if (swordArr[i] != null && swordArr[i].targetHit)
			{
				allowDetonate = true;
				break;
			}
		}
		if (!allowDetonate)
		{
			yield break;
		}
		string holdStr = "Skill" + skillSlot;
		int delayStopwatchID = ChaosStopwatch.Begin(1.75f);
		allowDetonate = false;
		parent.overheadPrompt.DisplayPrompt("Slot" + skillSlot, loop: true);
		while (!ChaosStopwatch.Check(delayStopwatchID))
		{
			if (parent.inputDevice.GetButton(holdStr))
			{
				allowDetonate = true;
				ChaosStopwatch.Stop(delayStopwatchID);
			}
			yield return null;
		}
		parent.overheadPrompt.HidePrompt(string.Empty);
		if (!allowDetonate)
		{
			yield break;
		}
		for (int j = 0; j < swordArr.Length; j++)
		{
			ChaosSwordProjectile tempCS = swordArr[j];
			swordArr[j] = null;
			if (tempCS != null && tempCS.targetHit)
			{
				tempCS.flyTime = 0.125f * (float)j;
				tempCS.RefreshFlightTime();
			}
		}
	}
}
public class UseChaosWeapons : UseBuffSkill
{
	public new static string staticID = "UseChaosWeapons";
	private const int MaxCount = 7;
	private static int[] arrangeArray = new int[7] { 0, 6, 1, 5, 2, 4, 3 };
	private ChaosWeapon[] cwArray = new ChaosWeapon[7];
	private ChaosWeapon currentCW;
	private Vector2 curDirVec;
	private int ActiveIndex
	{
		get
		{
			for (int i = 0; i < 7; i++)
			{
				if (cwArray[i] != null && !cwArray[i].releaseQueued)
				{
					return i;
				}
			}
			return -1;
		}
	}
	public UseChaosWeapons(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		empoweredStat.SetInitialBaseValue(newBaseVal: true);
		isProjectileSkill = true;
		whileStopwatch.SetDelay(0.125f);
	}
	public override void SetEmpowered(bool gs, BoolVarStatMod gm)
	{
	}
	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		Vector2 vector = (Vector2)parent.attackOriginTrans.position - inputVector;
		ChaosBurst.Spawn(vector, 3);
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(vector, "Depart", 0.2f);
		parent.movement.moveVector = Entity.GetFacingDirectionVector(parent.facingDirection);
		for (int i = 0; i < 7; i++)
		{
			cwArray[i] = CreateChaosWeapon(vector, i);
		}
		CameraController.ShakeCamera(0.3f);
