	public class UseDragonGrade : SkillState
	{
		public new static string staticID = "UseDragonGrade";
		private bool checkSkills = true;
		private bool fireUnlocked;
		private bool airUnlocked;
		private bool earthUnlocked;
		private bool thunderUnlocked;
		private bool waterUnlocked;
		private Vector2 currPos;
		private Vector2 perpendVec;
		private Vector2 atkPos;
		private Vector2 atkVec;
		private Quaternion atkQuat;
		private int atkCounter;
		private bool atkStarted;
		public override string OnEnterAnimStr => parent.PBAoEAnimStr;
		public UseDragonGrade(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			empoweredStat.SetInitialBaseValue(newBaseVal: true);
			SetAnimTimes(0f, 0.2f, 0.1f, 0.5f, 0.65f);
			Player player = parent;
			player.assignSkillSlotEventHandlers = (AssignSkillSlotEventHandler)Delegate.Remove(player.assignSkillSlotEventHandlers, new AssignSkillSlotEventHandler(OnSkillAssign));
			Player player2 = parent;
			player2.assignSkillSlotEventHandlers = (AssignSkillSlotEventHandler)Delegate.Combine(player2.assignSkillSlotEventHandlers, new AssignSkillSlotEventHandler(OnSkillAssign));
		}
		public override void SetEmpowered(bool gs, BoolVarStatMod gm)
		{
		}
		private void OnSkillAssign(SkillState state, int slot)
		{
			checkSkills = true;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			CheckForDragons();
			atkStarted = false;
			CameraController.ShakeCamera(0.2f);
		}
		private void CheckForDragons()
		{
			if (checkSkills && Globals.InGameScene(string.Empty))
			{
				checkSkills = false;
				if (!fireUnlocked && parent.HasSkill(ShootFireArc.staticID))
				{
					fireUnlocked = true;
					HandleSkillLoss(ShootFireArc.staticID);
				}
				if (!airUnlocked && parent.HasSkill(UseDragonBreath.staticID))
				{
					airUnlocked = true;
					HandleSkillLoss(UseDragonBreath.staticID);
				}
				if (!earthUnlocked && parent.HasSkill(UseDragonStomp.staticID))
				{
					earthUnlocked = true;
					HandleSkillLoss(UseDragonStomp.staticID);
				}
				if (!thunderUnlocked && parent.HasSkill(UseShockDragon.staticID))
				{
					thunderUnlocked = true;
					HandleSkillLoss(UseShockDragon.staticID);
				}
				if (!waterUnlocked && parent.HasSkill(UseAquaDragon.staticID))
				{
					waterUnlocked = true;
					HandleSkillLoss(UseAquaDragon.staticID);
				}
			}
		}
		private void HandleSkillLoss(string givenID)
		{
			if (parent.GetSignatureSkill().skillID != givenID)
			{
				parent.RemoveSkill(givenID);
			}
		}
		public override void ExecuteSkill()
		{
			if (!atkStarted)
			{
				atkStarted = true;
				atkCounter = 0;
				atkVec = inputVector;
				atkPos = parent.attackOriginTrans.position;
				atkQuat = Globals.GetRotationQuaternion(atkVec);
				currPos = parent.transform.position;
				perpendVec = Globals.GetPerpendicular(atkVec);
			}
			switch (atkCounter)
			{
			case 0:
				CreateChaos();
				break;
			case 1:
				if (fireUnlocked)
				{
					CreateArc(perpendVec * 0.5f, givenArc: false);
					CreateArc(-perpendVec * 0.5f, givenArc: true);
				}
				break;
			case 2:
				if (airUnlocked)
				{
					CreateBlast();
				}
				break;
			case 3:
				if (earthUnlocked)
				{
					CreateDive(perpendVec * 0.75f);
				}
				break;
			case 4:
				if (thunderUnlocked)
				{
					CreateCircuit(perpendVec);
				}
				break;
			case 5:
				if (waterUnlocked)
				{
					CreateSurge();
				}
				break;
			default:
				base.ExecuteSkill();
				break;
			}
			atkCounter++;
		}
		private void CreateChaos()
		{
			ChaosInst<DragonGrade>(DragonGrade.Prefab, currPos + atkVec * 4f).Init(parent.facingDirection, parent.skillCategory, skillID, atkVec);
		}
		private void CreateArc(Vector2 givenOffset, bool givenArc)
		{
			FireArc fireArc = (FireArc)Projectile.CreateProjectile(parent, FireArc.Prefab, atkPos + atkVec + givenOffset, atkQuat, parent.transform.parent);
			fireArc.attackBox.SetAttackInfo(parent.skillCategory, ShootFireArc.staticID);
			fireArc.UpdateCalculatedDamage(initDamageOverride: true);
			fireArc.targetVector = atkVec;
			fireArc.attackBox.knockbackOverwriteVector = atkVec;
			fireArc.positiveApproach = givenArc;
			fireArc.arcRange = 5f;
			fireArc.flyTime = 0.75f;
			fireArc = (FireArc)Projectile.CreateProjectile(parent, FireArc.Prefab, atkPos + givenOffset * 1.5f, atkQuat, parent.transform.parent);
			fireArc.attackBox.SetAttackInfo(parent.skillCategory, ShootFireArc.staticID);
			fireArc.UpdateCalculatedDamage(initDamageOverride: true);
			fireArc.targetVector = atkVec;
			fireArc.attackBox.knockbackOverwriteVector = atkVec;
			fireArc.positiveApproach = !givenArc;
			fireArc.arcRange = 5f;
			fireArc.flyTime = 0.75f;
			fireArc = (FireArc)Projectile.CreateProjectile(parent, FireArc.Prefab, atkPos - atkVec + givenOffset * 2.5f, atkQuat, parent.transform.parent);
			fireArc.attackBox.SetAttackInfo(parent.skillCategory, ShootFireArc.staticID);
			fireArc.UpdateCalculatedDamage(initDamageOverride: true);
			fireArc.targetVector = atkVec;
			fireArc.attackBox.knockbackOverwriteVector = atkVec;
			fireArc.positiveApproach = givenArc;
			fireArc.arcRange = 5f;
			fireArc.flyTime = 0.75f;
		}
		private void CreateBlast()
		{
			DragonBreath dragonBreath = ChaosInst<DragonBreath>(DragonBreath.Prefab, atkPos + atkVec * 1.375f, atkQuat);
			dragonBreath.attack.SetAttackInfo(parent.skillCategory, UseDragonBreath.staticID);
			dragonBreath.attack.knockbackOverwriteVector = atkVec;
			dragonBreath.attackVector = atkVec;
			dragonBreath.facingDirection = parent.facingDirection;
			dragonBreath.hitCount = 3;
			dragonBreath.blastDelay = 0.25f;
		}
		private void CreateCircuit(Vector2 givenOffset)
		{
			ShockDragon shockDragon = (ShockDragon)Projectile.CreateProjectile(parent, ShockDragon.Prefab, atkPos + givenOffset, Quaternion.identity, parent.transform.parent);
			shockDragon.attackBox.SetAttackInfo(parent.skillCategory, UseShockDragon.staticID);
			shockDragon.UpdateCalculatedDamage(initDamageOverride: true);
			shockDragon.Init(atkVec, 1, 0, isPos: false, isEmp: false, isUlt: false, parent.playerSummonsList);
			shockDragon.isEmpowered = true;
			shockDragon = (ShockDragon)Projectile.CreateProjectile(parent, ShockDragon.Prefab, atkPos - givenOffset, Quaternion.identity, parent.transform.parent);
			shockDragon.attackBox.SetAttackInfo(parent.skillCategory, UseShockDragon.staticID);
			shockDragon.UpdateCalculatedDamage(initDamageOverride: true);
			shockDragon.Init(atkVec, 1, 0, isPos: true, isEmp: false, isUlt: false, parent.playerSummonsList);
			shockDragon.isEmpowered = true;
		}
		private void CreateDive(Vector2 givenOffset)
		{
			DragonStomp dragonStomp = ChaosInst<DragonStomp>(DragonStomp.Prefab, currPos + givenOffset);
			dragonStomp.SetSkillData(parent.skillCategory, UseDragonStomp.staticID);
