		private void CreateSurge()
		{
			AquaDragon aquaDragon = ChaosInst<AquaDragon>(AquaDragon.Prefab, atkPos + atkVec);
			aquaDragon.attack.SetAttackInfo(parent.skillCategory, UseAquaDragon.staticID);
